insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f2', 'orcamento-pessoal-1-quiz', 'O que é um gasto fixo?', array['Um gasto que só acontece uma vez por ano', 'Um gasto que se repete todo mês com o mesmo valor', 'Um gasto que muda toda semana, como o lazer', 'Um gasto que dá para deixar de pagar sem consequência']::text[], 1, 'facil', 'Gastos fixos se repetem com o mesmo valor, como aluguel, internet e mensalidades. Já os variáveis mudam de mês para mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f3', 'orcamento-pessoal-1-quiz', 'Qual destes é um exemplo de gasto fixo?', array['Compra de roupas em promoção', 'Passeio de fim de semana', 'Aluguel de valor combinado', 'Lanche na saída da aula']::text[], 2, 'facil', 'O aluguel combinado em contrato tem o mesmo valor todo mês. Roupas, passeios e lanches variam conforme o mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f4', 'orcamento-pessoal-1-quiz', 'Qual é o primeiro passo para montar um orçamento?', array['Investir todo o dinheiro disponível', 'Fazer um empréstimo para ter folga', 'Cortar todo o lazer de uma vez', 'Conhecer a sua renda e anotar os gastos']::text[], 3, 'facil', 'Sem saber quanto entra e para onde o dinheiro vai, não dá para planejar. Por isso se começa pela renda e pela anotação dos gastos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f5', 'orcamento-pessoal-1-quiz', 'Para que serve anotar os gastos durante um mês?', array['Para descobrir para onde o dinheiro vai', 'Para aumentar a renda automaticamente', 'Para pagar menos impostos', 'Para nunca mais precisar revisar o orçamento']::text[], 0, 'facil', 'A anotação mostra os números reais do seu mês e revela onde o dinheiro está indo, inclusive nos gastos pequenos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f6', 'orcamento-pessoal-1-quiz', 'Qual destes é um exemplo de renda?', array['O aluguel pago ao proprietário', 'A conta de luz do mês', 'A bolsa de estudos recebida todo mês', 'A parcela do celular']::text[], 2, 'facil', 'Renda é todo dinheiro que entra, como salário, bolsa e trabalhos extras. Aluguel, luz e parcela são gastos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f7', 'orcamento-pessoal-1-quiz', 'Qual destes gastos costuma mudar de um mês para o outro?', array['Mensalidade da faculdade com valor fixo', 'Alimentação fora de casa', 'Aluguel combinado em contrato', 'Parcela fixa de um financiamento']::text[], 1, 'facil', 'Gastos como alimentação fora de casa, transporte por aplicativo e lazer variam conforme o mês, por isso são gastos variáveis.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f8', 'orcamento-pessoal-1-quiz', 'Se a renda do mês é maior que os gastos, o que acontece?', array['Sobra dinheiro no fim do mês', 'Falta dinheiro no fim do mês', 'Os gastos viram dívida', 'A renda do mês seguinte diminui']::text[], 0, 'facil', 'Quando o que entra é maior que o que sai, sobra dinheiro, e essa sobra pode virar reserva ou ajudar numa meta.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-f9', 'orcamento-pessoal-1-quiz', 'Onde se pode anotar os gastos?', array['Só num programa pago de contabilidade', 'Só no aplicativo do banco', 'Só no fim do ano, de memória', 'No caderno, numa planilha ou no celular']::text[], 3, 'facil', 'O que importa é anotar com regularidade. Caderno, planilha e celular funcionam igualmente bem.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m4', 'orcamento-pessoal-1-quiz', 'Renda de R$ 2.200,00 no mês, gastos fixos de R$ 1.150,00 e variáveis de R$ 700,00. Quanto sobra?', array['R$ 1.050,00', 'R$ 1.500,00', 'R$ 1.850,00', 'R$ 350,00']::text[], 3, 'medio', 'Os gastos somam R$ 1.150,00 + R$ 700,00 = R$ 1.850,00. Sobram R$ 2.200,00 − R$ 1.850,00 = R$ 350,00. Descontar só um dos grupos de gasto é um erro comum.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m5', 'orcamento-pessoal-1-quiz', 'A renda foi de R$ 1.600,00, os gastos fixos somaram R$ 900,00 e os variáveis, R$ 850,00. Qual é o resultado do mês?', array['Faltaram R$ 150,00', 'Sobraram R$ 150,00', 'Sobraram R$ 700,00', 'Faltaram R$ 850,00']::text[], 0, 'medio', 'Os gastos são R$ 900,00 + R$ 850,00 = R$ 1.750,00, maiores que a renda de R$ 1.600,00. Faltaram R$ 150,00, e a anotação mostra onde dá para cortar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m6', 'orcamento-pessoal-1-quiz', 'Camila toma um café de R$ 7,50 todos os dias, e o mês tem 30 dias. Quanto ela gasta com café no mês?', array['R$ 150,00', 'R$ 187,50', 'R$ 225,00', 'R$ 112,50']::text[], 2, 'medio', 'Basta multiplicar o valor pelos dias: R$ 7,50 × 30 = R$ 225,00. Gastos pequenos e diários somam bastante no fim do mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m7', 'orcamento-pessoal-1-quiz', 'Três assinaturas custam R$ 19,90, R$ 34,90 e R$ 12,90 por mês. Quanto elas somam em um ano?', array['R$ 67,70', 'R$ 812,40', 'R$ 406,20', 'R$ 135,40']::text[], 1, 'medio', 'Por mês são R$ 67,70. Em 12 meses: R$ 67,70 × 12 = R$ 812,40. Pequenas assinaturas viram um gasto relevante ao longo do ano.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m8', 'orcamento-pessoal-1-quiz', 'A parcela do curso de inglês é de R$ 280,00 todo mês durante um ano. Esse gasto é:', array['fixo, porque se repete com o mesmo valor', 'variável, porque é um gasto com estudo', 'variável, porque dura só um ano', 'renda, porque traz um benefício']::text[], 0, 'medio', 'O que define um gasto fixo é repetir o mesmo valor em cada mês, e não o tipo de gasto. A parcela do curso segue essa regra.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m9', 'orcamento-pessoal-1-quiz', 'Qual destes pares é formado só por gastos fixos?', array['Cinema e passeios no fim de semana', 'Aluguel e mensalidade da academia', 'Roupas novas e lanches fora de casa', 'Presentes e viagens de férias']::text[], 1, 'medio', 'Aluguel e mensalidade da academia se repetem com o mesmo valor. Cinema, roupas, lanches, presentes e viagens mudam de mês para mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m10', 'orcamento-pessoal-1-quiz', 'Uma pessoa paga R$ 5,50 por viagem de ônibus, faz 2 viagens por dia e trabalha 22 dias no mês. Quanto gasta com transporte?', array['R$ 121,00', 'R$ 363,00', 'R$ 242,00', 'R$ 484,00']::text[], 2, 'medio', 'Em um dia são 2 viagens: R$ 5,50 × 2 = R$ 11,00. Em 22 dias: R$ 11,00 × 22 = R$ 242,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m11', 'orcamento-pessoal-1-quiz', 'Rafael recebe R$ 2.000,00 e gasta R$ 500,00 com alimentação. Que parte da renda isso representa?', array['20%', '30%', '40%', '25%']::text[], 3, 'medio', 'Divide-se o gasto pela renda: R$ 500,00 ÷ R$ 2.000,00 = 0,25, ou seja, 25%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m12', 'orcamento-pessoal-1-quiz', 'Um designer recebeu R$ 1.200,00, R$ 1.800,00 e R$ 1.500,00 em três meses seguidos. Qual foi a renda média mensal?', array['R$ 1.500,00', 'R$ 1.800,00', 'R$ 1.200,00', 'R$ 4.500,00']::text[], 0, 'medio', 'A média é a soma dividida pelo número de meses: (R$ 1.200,00 + R$ 1.800,00 + R$ 1.500,00) ÷ 3 = R$ 1.500,00. Para uma renda que varia, a média ajuda a planejar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m13', 'orcamento-pessoal-1-quiz', 'Sobram R$ 250,00 por mês e o dinheiro fica guardado, sem render. Quanto haverá depois de 6 meses?', array['R$ 1.250,00', 'R$ 1.750,00', 'R$ 3.000,00', 'R$ 1.500,00']::text[], 3, 'medio', 'Sem rendimento, é só multiplicar: R$ 250,00 × 6 = R$ 1.500,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m14', 'orcamento-pessoal-1-quiz', 'Quando os gastos passam da renda, qual atitude ajuda mais?', array['Pagar tudo no cartão para adiar o problema', 'Parar de anotar os gastos', 'Revisar os gastos variáveis e ver onde dá para cortar', 'Pegar um empréstimo todo mês para cobrir a diferença']::text[], 2, 'medio', 'Os gastos variáveis são os mais fáceis de ajustar. Adiar o problema ou pegar empréstimo só aumenta a dívida.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m15', 'orcamento-pessoal-1-quiz', 'Por que os gastos pequenos também devem ser anotados?', array['Porque a lei obriga a registrar tudo', 'Porque, somados no mês, podem pesar bastante', 'Porque gastos pequenos não entram na renda', 'Porque eles nunca mudam de valor']::text[], 1, 'medio', 'Um lanche, um café ou uma assinatura parecem pouco, mas se repetem. A soma deles no mês costuma surpreender.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-m16', 'orcamento-pessoal-1-quiz', 'No mês passado, Júlia recebeu R$ 2.000,00, teve R$ 1.100,00 de gastos fixos e sobraram R$ 250,00. Quanto ela gastou com variáveis?', array['R$ 900,00', 'R$ 650,00', 'R$ 1.350,00', 'R$ 250,00']::text[], 1, 'medio', 'Gastos totais: R$ 2.000,00 − R$ 250,00 = R$ 1.750,00. Tirando os fixos de R$ 1.100,00, sobram R$ 650,00 de gastos variáveis.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-d1', 'orcamento-pessoal-1-quiz', 'Os gastos fixos de Bia correspondem a 55% de uma renda de R$ 2.600,00, e os variáveis somam R$ 780,00. Quanto sobra?', array['R$ 1.170,00', 'R$ 1.820,00', 'R$ 2.210,00', 'R$ 390,00']::text[], 3, 'dificil', 'Fixos: R$ 2.600,00 × 0,55 = R$ 1.430,00. Total de gastos: R$ 1.430,00 + R$ 780,00 = R$ 2.210,00. Sobram R$ 2.600,00 − R$ 2.210,00 = R$ 390,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-d2', 'orcamento-pessoal-1-quiz', 'Tiago quer que sobrem pelo menos R$ 400,00 por mês. A renda é R$ 2.350,00 e os gastos fixos são R$ 1.280,00. Qual é o máximo que ele pode gastar com variáveis?', array['R$ 670,00', 'R$ 1.070,00', 'R$ 400,00', 'R$ 1.950,00']::text[], 0, 'dificil', 'Do que sobra depois dos fixos (R$ 2.350,00 − R$ 1.280,00 = R$ 1.070,00), ainda se separam R$ 400,00. Restam R$ 670,00 para os variáveis.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-1-d3', 'orcamento-pessoal-1-quiz', 'No mês 1, a renda foi R$ 2.400,00 e os gastos, R$ 2.150,00. No mês 2, a renda foi R$ 2.400,00 e os gastos, R$ 2.520,00. Qual afirmação está correta?', array['Nos dois meses sobrou dinheiro', 'No mês 1 faltaram R$ 250,00 e no mês 2 sobraram R$ 120,00', 'No mês 1 sobraram R$ 250,00 e no mês 2 faltaram R$ 120,00', 'No mês 2 sobraram R$ 2.520,00']::text[], 2, 'dificil', 'Mês 1: R$ 2.400,00 − R$ 2.150,00 = R$ 250,00 de sobra. Mês 2: R$ 2.400,00 − R$ 2.520,00 = −R$ 120,00, ou seja, faltaram R$ 120,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f2', 'orcamento-pessoal-2-quiz', 'O que é uma meta financeira?', array['Um limite de crédito liberado pelo banco', 'Um tipo de imposto sobre a renda', 'Um objetivo para o seu dinheiro, como uma viagem', 'Um gasto fixo que se repete todo mês']::text[], 2, 'facil', 'Meta é um objetivo com valor e prazo, como trocar de celular, viajar ou formar uma reserva. Ordenar as metas por prioridade ajuda a montar o orçamento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f3', 'orcamento-pessoal-2-quiz', 'Na divisão 50/30/20, qual parte representa os desejos?', array['50% da renda', '30% da renda', '20% da renda', '10% da renda']::text[], 1, 'facil', 'Na divisão 50/30/20, 50% vão para as necessidades, 30% para os desejos e 20% para guardar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f4', 'orcamento-pessoal-2-quiz', 'Qual destes é um exemplo de necessidade?', array['Assinatura de um serviço de streaming', 'Viagem de férias com a família', 'Compra de um jogo novo no lançamento', 'Comida e transporte para o trabalho']::text[], 3, 'facil', 'Necessidades são os gastos de que você não abre mão, como moradia, comida e transporte. Os demais são desejos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f5', 'orcamento-pessoal-2-quiz', 'Qual destes é um exemplo de desejo?', array['Ir ao cinema com os amigos', 'Pagar o aluguel', 'Pagar a conta de luz', 'Comprar a passagem para o trabalho']::text[], 0, 'facil', 'Desejos são gastos de que se pode abrir mão, como lazer e compras. Aluguel, luz e passagem são necessidades.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-f6', 'orcamento-pessoal-2-quiz', 'Com que frequência convém revisar o orçamento?', array['Só quando a renda cair', 'Uma vez a cada cinco anos', 'Nunca, depois de montado', 'Todo mês']::text[], 3, 'facil', 'A vida muda, e o plano precisa acompanhar. Por isso o orçamento é revisado todo mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m3', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 4.000,00 e a divisão 50/30/20, quanto vai para os desejos?', array['R$ 800,00', 'R$ 1.200,00', 'R$ 2.000,00', 'R$ 400,00']::text[], 1, 'medio', 'Os desejos ficam com 30% da renda: R$ 4.000,00 × 0,30 = R$ 1.200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m4', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 2.500,00 e a divisão 50/30/20, quanto se guarda por mês?', array['R$ 500,00', 'R$ 250,00', 'R$ 750,00', 'R$ 1.250,00']::text[], 0, 'medio', 'Guardar corresponde a 20% da renda: R$ 2.500,00 × 0,20 = R$ 500,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m5', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 1.800,00 e a divisão 50/30/20, quanto vai para os desejos?', array['R$ 360,00', 'R$ 900,00', 'R$ 540,00', 'R$ 600,00']::text[], 2, 'medio', 'Os desejos recebem 30%: R$ 1.800,00 × 0,30 = R$ 540,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m6', 'orcamento-pessoal-2-quiz', 'Guardando 20% de uma renda de R$ 3.200,00 todo mês, quanto se acumula em 5 meses, sem contar rendimento?', array['R$ 3.200,00', 'R$ 640,00', 'R$ 1.600,00', 'R$ 3.840,00']::text[], 0, 'medio', 'Por mês se guarda R$ 3.200,00 × 0,20 = R$ 640,00. Em 5 meses: R$ 640,00 × 5 = R$ 3.200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m7', 'orcamento-pessoal-2-quiz', 'Por que os percentuais 50/30/20 somam 100%?', array['Porque 100% é o limite do cartão', 'Porque dividem toda a renda do mês', 'Porque a lei exige essa soma', 'Porque a poupança rende 100% ao ano']::text[], 1, 'medio', 'Um bom orçamento dá um destino para toda a renda: parte para necessidades, parte para desejos e parte para guardar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m8', 'orcamento-pessoal-2-quiz', 'O aluguel de uma pessoa pesa mais do que 50% da renda. O que a lição sugere?', array['Abandonar o orçamento até o aluguel baixar', 'Deixar de guardar até o aluguel diminuir', 'Tirar o aluguel do orçamento', 'Ajustar os percentuais, sem deixar de guardar']::text[], 3, 'medio', 'A divisão 50/30/20 é uma sugestão, não uma lei. Dá para ajustar os percentuais, mas sempre mantendo uma parte para guardar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m9', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 2.800,00, os 50% para necessidades dariam R$ 1.400,00. Se as necessidades reais são R$ 1.680,00, quanto elas passam do planejado?', array['R$ 140,00', 'R$ 560,00', 'R$ 280,00', 'R$ 1.400,00']::text[], 2, 'medio', 'As necessidades reais passam do limite em R$ 1.680,00 − R$ 1.400,00 = R$ 280,00. Será preciso ajustar o orçamento, por exemplo diminuindo os desejos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m10', 'orcamento-pessoal-2-quiz', 'Marcos listou metas: um celular novo, uma viagem e a reserva de emergência. O que fazer primeiro?', array['Gastar com a viagem primeiro', 'Ordenar as metas por prioridade', 'Descartar a reserva de emergência', 'Pegar um empréstimo para realizar todas']::text[], 1, 'medio', 'Com várias metas, o primeiro passo é ordená-las por prioridade e só então definir quanto da renda vai para cada uma.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m11', 'orcamento-pessoal-2-quiz', 'Um celular custa R$ 1.440,00. Guardando 20% de uma renda de R$ 1.200,00 por mês, em quantos meses a pessoa junta o valor, sem rendimento?', array['6 meses', '4 meses', '8 meses', '12 meses']::text[], 0, 'medio', 'Por mês se guarda R$ 1.200,00 × 0,20 = R$ 240,00. Para juntar R$ 1.440,00: R$ 1.440,00 ÷ R$ 240,00 = 6 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m12', 'orcamento-pessoal-2-quiz', 'Qual afirmação sobre a divisão 50/30/20 está correta?', array['É uma lei que todo mundo deve seguir', 'Só vale para quem ganha mais de cinco salários', 'É um ponto de partida que pode ser ajustado', 'Obriga a gastar 30% com lazer']::text[], 2, 'medio', 'A divisão 50/30/20 serve de ponto de partida. Cada pessoa ajusta os percentuais à sua realidade, sem deixar de guardar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m13', 'orcamento-pessoal-2-quiz', 'Com renda de R$ 3.600,00 na divisão 50/30/20, quanto sobra somando o que vai para os desejos e para guardar?', array['R$ 720,00', 'R$ 1.080,00', 'R$ 2.520,00', 'R$ 1.800,00']::text[], 3, 'medio', 'Desejos (30%) e guardar (20%) somam 50% da renda: R$ 3.600,00 × 0,50 = R$ 1.800,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-m14', 'orcamento-pessoal-2-quiz', 'A renda de uma pessoa sobe de R$ 2.000,00 para R$ 2.400,00, e ela mantém os 20% para guardar. Quanto passa a guardar a mais por mês?', array['R$ 400,00', 'R$ 80,00', 'R$ 480,00', 'R$ 200,00']::text[], 1, 'medio', 'Antes: R$ 2.000,00 × 0,20 = R$ 400,00. Depois: R$ 2.400,00 × 0,20 = R$ 480,00. A diferença é de R$ 80,00 por mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d2', 'orcamento-pessoal-2-quiz', 'Ana ganha R$ 2.700,00 e as necessidades consomem R$ 1.800,00. Se ela mantiver 20% para guardar, quanto sobra para os desejos?', array['R$ 810,00', 'R$ 900,00', 'R$ 540,00', 'R$ 360,00']::text[], 3, 'dificil', 'Guardar 20% de R$ 2.700,00 dá R$ 540,00. Restam R$ 2.700,00 − R$ 1.800,00 − R$ 540,00 = R$ 360,00 para os desejos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d3', 'orcamento-pessoal-2-quiz', 'Pela divisão 50/30/20, qual renda mínima faz com que necessidades de R$ 1.650,00 caibam nos 50%?', array['R$ 825,00', 'R$ 2.475,00', 'R$ 3.300,00', 'R$ 8.250,00']::text[], 2, 'dificil', 'Se R$ 1.650,00 são 50% da renda, a renda é R$ 1.650,00 ÷ 0,50 = R$ 3.300,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d4', 'orcamento-pessoal-2-quiz', 'Beatriz ganha R$ 3.000,00, e as necessidades somam R$ 1.950,00 (65% da renda). Ela quer guardar 20%. Quanto sobra para os desejos?', array['R$ 450,00 (15% da renda)', 'R$ 900,00 (30% da renda)', 'R$ 1.050,00 (35% da renda)', 'R$ 600,00 (20% da renda)']::text[], 0, 'dificil', 'Guardar 20% são R$ 600,00. Sobram R$ 3.000,00 − R$ 1.950,00 − R$ 600,00 = R$ 450,00, que é 15% da renda. Quando as necessidades pesam mais, os desejos encolhem.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d5', 'orcamento-pessoal-2-quiz', 'Uma pessoa guarda 20% da renda de R$ 2.000,00. Depois de um aumento de 10% na renda, ela mantém os 20%. Quanto guarda por mês agora?', array['R$ 410,00', 'R$ 420,00', 'R$ 440,00', 'R$ 480,00']::text[], 2, 'dificil', 'A nova renda é R$ 2.000,00 × 1,10 = R$ 2.200,00. Guardando 20%: R$ 2.200,00 × 0,20 = R$ 440,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d6', 'orcamento-pessoal-2-quiz', 'Para juntar R$ 5.400,00 para uma viagem, guardando 20% de uma renda de R$ 2.250,00, sem rendimento, quantos meses são necessários?', array['10 meses', '15 meses', '24 meses', '12 meses']::text[], 3, 'dificil', 'Guarda-se R$ 2.250,00 × 0,20 = R$ 450,00 por mês. Para chegar a R$ 5.400,00: R$ 5.400,00 ÷ R$ 450,00 = 12 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d7', 'orcamento-pessoal-2-quiz', 'Pedro divide a renda de R$ 2.400,00 em 55% para necessidades, 25% para desejos e 20% para guardar. Qual afirmação é verdadeira?', array['Ele guarda R$ 480,00 e gasta R$ 600,00 com desejos', 'Ele guarda R$ 600,00 e gasta R$ 480,00 com desejos', 'Ele gasta R$ 1.200,00 com necessidades', 'A divisão é inválida, porque não é 50/30/20']::text[], 0, 'dificil', '20% de R$ 2.400,00 são R$ 480,00 para guardar; 25% são R$ 600,00 para os desejos; e 55% são R$ 1.320,00 para as necessidades. A 50/30/20 é só uma sugestão.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-2-d8', 'orcamento-pessoal-2-quiz', 'Uma pessoa corta R$ 150,00 de desejos por mês e passa esse valor para a reserva. Quanto terá a mais depois de 8 meses, sem rendimento?', array['R$ 150,00', 'R$ 1.200,00', 'R$ 600,00', 'R$ 1.800,00']::text[], 1, 'dificil', 'Cada mês vão R$ 150,00 para guardar: R$ 150,00 × 8 = R$ 1.200,00. Pequenas trocas no orçamento, repetidas, fazem diferença.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f2', 'orcamento-pessoal-3-quiz', 'Qual é a meta comum para a reserva de emergência?', array['Um mês de salário bruto, no máximo', 'Dois anos de toda a renda guardada', 'O valor de um carro usado', 'De 3 a 6 meses dos gastos essenciais']::text[], 3, 'facil', 'A meta usual é guardar de 3 a 6 meses dos gastos essenciais, os de que você não abre mão.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f3', 'orcamento-pessoal-3-quiz', 'O que é liquidez?', array['O lucro anual de uma aplicação', 'A facilidade de resgatar o dinheiro', 'O risco de perder dinheiro', 'A taxa cobrada pelo banco']::text[], 1, 'facil', 'Liquidez é o quanto uma aplicação pode virar dinheiro rapidamente. Para a reserva, isso importa mais do que render muito.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f4', 'orcamento-pessoal-3-quiz', 'Qual situação justifica usar a reserva de emergência?', array['Comprar um celular novo em promoção', 'Fazer uma viagem de férias', 'Um conserto urgente e imprevisto', 'Pagar o lazer do fim de semana']::text[], 2, 'facil', 'A reserva é para imprevistos, como um conserto urgente, uma despesa de saúde ou a perda de renda.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f5', 'orcamento-pessoal-3-quiz', 'Como a lição recomenda começar a reserva?', array['Com um valor pequeno, guardado todo mês', 'Só depois de realizar todas as outras metas', 'Esperando sobrar dinheiro no fim do ano', 'Com um valor grande, de uma só vez']::text[], 0, 'facil', 'Começar pequeno e guardar um valor fixo todo mês, de preferência assim que receber, cria o hábito.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-f6', 'orcamento-pessoal-3-quiz', 'O que são gastos essenciais?', array['Os de que você não abre mão, como moradia', 'Todos os gastos do mês', 'Os gastos com lazer', 'Os gastos que podem ser adiados para sempre']::text[], 0, 'facil', 'Gastos essenciais incluem moradia, comida, transporte e contas básicas. São a base para calcular a reserva.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m2', 'orcamento-pessoal-3-quiz', 'Os gastos essenciais de uma pessoa são R$ 1.800,00 por mês. Qual é a meta de uma reserva de 6 meses?', array['R$ 5.400,00', 'R$ 3.600,00', 'R$ 10.800,00', 'R$ 21.600,00']::text[], 2, 'medio', 'Seis meses de gastos essenciais: R$ 1.800,00 × 6 = R$ 10.800,00. Três meses seriam R$ 5.400,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m3', 'orcamento-pessoal-3-quiz', 'Com gastos essenciais de R$ 1.500,00 por mês, a meta de 3 a 6 meses fica entre:', array['R$ 1.500,00 e R$ 3.000,00', 'R$ 4.500,00 e R$ 9.000,00', 'R$ 9.000,00 e R$ 18.000,00', 'R$ 3.000,00 e R$ 6.000,00']::text[], 1, 'medio', '3 meses: R$ 1.500,00 × 3 = R$ 4.500,00. 6 meses: R$ 1.500,00 × 6 = R$ 9.000,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m4', 'orcamento-pessoal-3-quiz', 'Guardando R$ 250,00 por mês, em quantos meses se junta R$ 3.000,00, sem rendimento?', array['10 meses', '15 meses', '24 meses', '12 meses']::text[], 3, 'medio', 'R$ 3.000,00 ÷ R$ 250,00 = 12 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m5', 'orcamento-pessoal-3-quiz', 'Por que é bom guardar o dinheiro da reserva logo que se recebe?', array['Porque os juros são maiores no primeiro dia do mês', 'Para o valor não ser gasto antes de ser guardado', 'Porque o banco exige esse horário', 'Porque assim os gastos fixos diminuem']::text[], 1, 'medio', 'Se a pessoa espera sobrar, muitas vezes nada sobra. Separar o valor assim que recebe transforma a reserva em prioridade.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m6', 'orcamento-pessoal-3-quiz', 'Qual característica é mais importante na aplicação da reserva de emergência?', array['Liquidez e baixo risco', 'Rendimento máximo, mesmo com risco alto', 'Prazo longo, com o dinheiro bloqueado', 'Promessa de retorno garantido de 100% ao ano']::text[], 0, 'medio', 'A reserva precisa estar disponível na hora do imprevisto e não pode correr o risco de perder valor. O rendimento fica em segundo plano.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m7', 'orcamento-pessoal-3-quiz', 'Joana tem gastos essenciais de R$ 2.000,00 por mês e uma reserva de R$ 7.000,00. Quantos meses de gastos essenciais a reserva cobre?', array['2,5 meses', '4,5 meses', '7 meses', '3,5 meses']::text[], 3, 'medio', 'R$ 7.000,00 ÷ R$ 2.000,00 = 3,5 meses, dentro da faixa de 3 a 6 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m8', 'orcamento-pessoal-3-quiz', 'Qual destes é um imprevisto que a reserva deve cobrir?', array['Pagar o aluguel do mês', 'Comprar um presente de aniversário planejado', 'Perder a fonte de renda de repente', 'Pagar uma anuidade avisada com antecedência']::text[], 2, 'medio', 'Imprevisto é o que não estava no plano, como perder a renda. Aluguel, presentes e anuidades já entram no orçamento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m9', 'orcamento-pessoal-3-quiz', 'Depois de usar parte da reserva num imprevisto, o que fazer?', array['Esquecer a reserva e seguir sem ela', 'Encerrar a reserva de vez', 'Voltar a guardar até recompor a meta', 'Gastar o que restou com lazer']::text[], 2, 'medio', 'A reserva existe para ser usada. Depois do imprevisto, o certo é recompor o valor aos poucos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m10', 'orcamento-pessoal-3-quiz', 'Os gastos essenciais eram R$ 1.200,00 e passaram a ser R$ 1.500,00. A meta mínima de 3 meses passa a ser de:', array['R$ 4.500,00', 'R$ 3.600,00', 'R$ 5.400,00', 'R$ 9.000,00']::text[], 0, 'medio', 'A meta mínima acompanha os gastos: R$ 1.500,00 × 3 = R$ 4.500,00. Por isso a reserva é revisada quando o custo de vida muda.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m11', 'orcamento-pessoal-3-quiz', 'Uma pessoa guarda R$ 300,00 por mês, sem rendimento. Quanto terá em 10 meses?', array['R$ 300,00', 'R$ 3.000,00', 'R$ 1.500,00', 'R$ 3.600,00']::text[], 1, 'medio', 'R$ 300,00 × 10 = R$ 3.000,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-m12', 'orcamento-pessoal-3-quiz', 'Qual aplicação combina melhor com a reserva de emergência?', array['Uma que só libera o dinheiro depois de 5 anos', 'Uma de risco alto, com chance de retorno enorme', 'Um terreno, que é difícil de vender', 'Uma de baixo risco, que pode ser resgatada rapidamente']::text[], 3, 'medio', 'Baixo risco e liquidez fazem a reserva estar disponível e inteira quando for preciso.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d3', 'orcamento-pessoal-3-quiz', 'Os gastos essenciais são R$ 2.200,00 por mês e a meta é de 6 meses. Já existem R$ 4.400,00 guardados e a pessoa guarda R$ 550,00 por mês. Em quantos meses chega à meta?', array['12 meses', '20 meses', '16 meses', '24 meses']::text[], 2, 'dificil', 'Meta: R$ 2.200,00 × 6 = R$ 13.200,00. Faltam R$ 13.200,00 − R$ 4.400,00 = R$ 8.800,00. R$ 8.800,00 ÷ R$ 550,00 = 16 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d4', 'orcamento-pessoal-3-quiz', 'Rita guarda R$ 400,00 por mês e seus gastos essenciais são R$ 1.600,00. Depois de 18 meses, a reserva cobre quantos meses de gastos essenciais?', array['3 meses', '6 meses', '4 meses', '4,5 meses']::text[], 3, 'dificil', 'Em 18 meses: R$ 400,00 × 18 = R$ 7.200,00. R$ 7.200,00 ÷ R$ 1.600,00 = 4,5 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d5', 'orcamento-pessoal-3-quiz', 'A reserva A tem R$ 6.000,00 e os gastos essenciais do dono são R$ 1.500,00. A reserva B tem R$ 9.000,00 e os gastos essenciais do dono são R$ 3.000,00. Qual afirmação está correta?', array['B dura mais, porque o valor é maior', 'A cobre 4 meses e B cobre 3 meses', 'As duas cobrem 3 meses', 'A cobre 6 meses e B cobre 3 meses']::text[], 1, 'dificil', 'A: R$ 6.000,00 ÷ R$ 1.500,00 = 4 meses. B: R$ 9.000,00 ÷ R$ 3.000,00 = 3 meses. O que importa é a relação com os gastos, e não o valor total.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d6', 'orcamento-pessoal-3-quiz', 'Mauro precisa juntar R$ 3.500,00. Guardando R$ 250,00 por mês, levaria 14 meses. Se ele cortar R$ 100,00 de gastos e passar a guardar R$ 350,00 por mês, quantos meses economiza?', array['4 meses', '2 meses', '5 meses', '6 meses']::text[], 0, 'dificil', 'Com R$ 350,00 por mês: R$ 3.500,00 ÷ R$ 350,00 = 10 meses. Antes eram R$ 3.500,00 ÷ R$ 250,00 = 14. A economia é de 4 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d7', 'orcamento-pessoal-3-quiz', 'Com a meta de 6 meses, os gastos essenciais caem de R$ 2.000,00 para R$ 1.700,00 depois de renegociar o aluguel. Quanto a meta da reserva diminui?', array['R$ 300,00', 'R$ 900,00', 'R$ 3.600,00', 'R$ 1.800,00']::text[], 3, 'dificil', 'A diferença nos gastos é de R$ 300,00 por mês. Em 6 meses: R$ 300,00 × 6 = R$ 1.800,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d8', 'orcamento-pessoal-3-quiz', 'A renda é R$ 3.000,00, e a pessoa guarda 20% por mês. Os gastos essenciais são R$ 1.800,00. Em quantos meses alcança a meta mínima de 3 meses?', array['6 meses', '12 meses', '9 meses', '18 meses']::text[], 2, 'dificil', 'Meta mínima: R$ 1.800,00 × 3 = R$ 5.400,00. Por mês se guarda R$ 3.000,00 × 0,20 = R$ 600,00. R$ 5.400,00 ÷ R$ 600,00 = 9 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d9', 'orcamento-pessoal-3-quiz', 'Qual destas atitudes vai contra o que se espera de uma reserva de emergência?', array['Colocar toda a reserva em uma única ação', 'Deixar a reserva numa aplicação com liquidez diária', 'Guardar um valor fixo todo mês', 'Revisar a meta quando os gastos mudam']::text[], 0, 'dificil', 'A reserva precisa estar inteira e disponível quando o imprevisto chegar. Uma ação pode cair de valor justamente nessa hora.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('orcamento-pessoal-3-d10', 'orcamento-pessoal-3-quiz', 'Léo recebe um 13º de R$ 2.400,00 e usa 50% para a reserva, que tinha R$ 1.800,00. A meta é de 3 meses de gastos essenciais de R$ 1.100,00. Depois do 13º, quanto ainda falta?', array['R$ 1.500,00', 'R$ 300,00', 'R$ 600,00', 'R$ 2.100,00']::text[], 1, 'dificil', 'Meta: R$ 1.100,00 × 3 = R$ 3.300,00. Com o 13º, a reserva vai a R$ 1.800,00 + R$ 1.200,00 = R$ 3.000,00. Faltam R$ 300,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f2', 'juros-compostos-1-quiz', 'O que são juros?', array['Um imposto cobrado sobre a renda', 'Uma tarifa cobrada só pelos bancos digitais', 'O "aluguel" do dinheiro: quem empresta recebe', 'O valor do dinheiro guardado em casa']::text[], 2, 'facil', 'Juros são o preço do dinheiro no tempo. Quem empresta, ou guarda numa aplicação, recebe; quem pega emprestado paga.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f3', 'juros-compostos-1-quiz', 'Nos juros simples, sobre qual valor a taxa incide todo mês?', array['Sobre o saldo do mês anterior, já com juros', 'Sempre sobre o valor inicial', 'Sobre a renda da pessoa', 'Sobre o valor da inflação']::text[], 1, 'facil', 'Nos juros simples a taxa incide só sobre o valor inicial, por isso os juros são os mesmos em todos os meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f4', 'juros-compostos-1-quiz', 'O que significa "juros sobre juros"?', array['A taxa de juros dobra todo mês', 'O banco cobra juros duas vezes', 'Os juros incidem só sobre o valor inicial', 'Os juros de cada mês também passam a render']::text[], 3, 'facil', 'Nos juros compostos, os juros que já foram somados ao saldo também rendem. É daí que vem a expressão "juros sobre juros".', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f5', 'juros-compostos-1-quiz', 'Para quem os juros compostos costumam pesar?', array['Para quem está devendo', 'Para quem guarda dinheiro todo mês', 'Para quem não tem renda', 'Para quem paga sempre à vista']::text[], 0, 'facil', 'Os juros compostos ajudam quem investe, porque o saldo rende sobre si mesmo, e pesam para quem deve, porque a dívida também cresce assim.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f6', 'juros-compostos-1-quiz', 'No começo, como é a diferença entre juros simples e compostos?', array['Enorme, mas diminui com o tempo', 'Nula durante os primeiros anos', 'Sempre a mesma, do começo ao fim', 'Pequena, mas cresce com o tempo']::text[], 3, 'facil', 'No primeiro mês os dois dão o mesmo resultado. Depois, os juros compostos passam a render sobre juros e a diferença só aumenta.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f7', 'juros-compostos-1-quiz', 'Qual é o juro simples de R$ 100,00 a 10% ao mês, depois de 1 mês?', array['R$ 1,00', 'R$ 10,00', 'R$ 100,00', 'R$ 110,00']::text[], 1, 'facil', 'R$ 100,00 × 10% = R$ 10,00. Atenção: R$ 110,00 seria o montante, que é o valor investido somado ao juro.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f8', 'juros-compostos-1-quiz', 'Quando você guarda dinheiro numa aplicação, quem recebe os juros?', array['Você, que emprestou o dinheiro', 'O banco que recebeu o dinheiro', 'O governo, que cobra o imposto', 'A empresa que emite o cartão']::text[], 0, 'facil', 'Na aplicação, você empresta o seu dinheiro e, por isso, recebe os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-f9', 'juros-compostos-1-quiz', 'Qual é a característica dos juros compostos?', array['A taxa incide só sobre o valor inicial', 'A taxa cai um pouco a cada mês', 'A taxa incide sobre o saldo, já com juros', 'Os juros são pagos uma única vez no fim']::text[], 2, 'facil', 'Nos juros compostos o saldo de cada mês, com os juros já somados, é a base de cálculo do mês seguinte.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m4', 'juros-compostos-1-quiz', 'R$ 5.000,00 rendem a juros simples de 2% ao mês durante 4 meses. Quanto foi de juros?', array['R$ 400,00', 'R$ 100,00', 'R$ 5.400,00', 'R$ 412,16']::text[], 0, 'medio', 'Os juros simples são iguais todo mês: R$ 5.000,00 × 2% = R$ 100,00. Em 4 meses: R$ 400,00. Os juros compostos seriam R$ 412,16.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m5', 'juros-compostos-1-quiz', 'R$ 1.500,00 rendem 3% ao mês a juros compostos. Qual é o saldo depois de 2 meses?', array['R$ 1.590,00', 'R$ 1.591,35', 'R$ 1.545,00', 'R$ 1.560,00']::text[], 1, 'medio', 'Mês 1: R$ 1.500,00 × 1,03 = R$ 1.545,00. Mês 2: R$ 1.545,00 × 1,03 = R$ 1.591,35. Juros simples dariam R$ 1.590,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m6', 'juros-compostos-1-quiz', 'R$ 2.000,00 rendem 5% ao ano a juros compostos. Qual é o saldo depois de 2 anos?', array['R$ 2.200,00', 'R$ 2.100,00', 'R$ 2.250,00', 'R$ 2.205,00']::text[], 3, 'medio', 'Ano 1: R$ 2.000,00 × 1,05 = R$ 2.100,00. Ano 2: R$ 2.100,00 × 1,05 = R$ 2.205,00. Os juros simples dariam R$ 2.200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m7', 'juros-compostos-1-quiz', 'R$ 1.000,00 rendem 2% ao mês. Depois de 3 meses, quanto o saldo a juros compostos supera o de juros simples?', array['R$ 0,12', 'R$ 12,10', 'R$ 1,21', 'R$ 61,21']::text[], 2, 'medio', 'Juros simples: R$ 1.060,00. Juros compostos: R$ 1.061,21. A diferença é pequena no começo, mas aumenta a cada mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m8', 'juros-compostos-1-quiz', 'Por que, nos juros compostos, o saldo cresce cada vez mais depressa?', array['Porque a taxa de juros sobe todo mês', 'Porque os juros de cada mês entram no saldo e passam a render', 'Porque o valor inicial é somado de novo todo mês', 'Porque o banco cobra uma tarifa menor com o tempo']::text[], 1, 'medio', 'A taxa é a mesma, mas incide sobre uma base maior a cada mês. Por isso o crescimento acelera.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m9', 'juros-compostos-1-quiz', 'Uma dívida de R$ 800,00 cresce 5% ao mês. Depois de 1 mês, quanto ela vale?', array['R$ 840,00', 'R$ 805,00', 'R$ 850,00', 'R$ 880,00']::text[], 0, 'medio', 'R$ 800,00 × 1,05 = R$ 840,00. No primeiro mês, juros simples e compostos dão o mesmo resultado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m10', 'juros-compostos-1-quiz', 'R$ 500,00 rendem 8% ao mês a juros compostos. Qual é o saldo depois de 2 meses?', array['R$ 580,00', 'R$ 540,00', 'R$ 583,20', 'R$ 590,00']::text[], 2, 'medio', 'Mês 1: R$ 500,00 × 1,08 = R$ 540,00. Mês 2: R$ 540,00 × 1,08 = R$ 583,20. Os juros simples dariam R$ 580,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m11', 'juros-compostos-1-quiz', 'Depois de 1 período, o que se pode dizer sobre juros simples e compostos?', array['Os compostos já rendem o dobro', 'Os simples rendem mais no 1º período', 'Os compostos nunca passam dos simples', 'Dão o mesmo resultado; a diferença vem depois']::text[], 3, 'medio', 'No primeiro período só existe o valor inicial para render. A diferença aparece quando os juros do primeiro período passam a render também.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m12', 'juros-compostos-1-quiz', 'R$ 3.000,00 rendem juros simples de 1,5% ao mês. Quanto de juros em 6 meses?', array['R$ 45,00', 'R$ 270,00', 'R$ 135,00', 'R$ 3.270,00']::text[], 1, 'medio', 'Por mês: R$ 3.000,00 × 1,5% = R$ 45,00. Em 6 meses: R$ 45,00 × 6 = R$ 270,00. Os R$ 3.270,00 seriam o montante, e não os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m13', 'juros-compostos-1-quiz', 'R$ 1.000,00 rendem 1% ao mês por 12 meses a juros compostos. Qual é o montante?', array['R$ 1.120,00', 'R$ 1.100,00', 'R$ 1.140,00', 'R$ 1.126,83']::text[], 3, 'medio', 'R$ 1.000,00 × 1,01¹² = R$ 1.126,83. Os juros simples dariam R$ 1.120,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m14', 'juros-compostos-1-quiz', 'Por que os juros compostos pesam mais numa dívida de longo prazo?', array['Porque a taxa fica maior sozinha', 'Porque o valor inicial dobra todo mês', 'Porque a dívida cresce sobre ela mesma', 'Porque o banco proíbe o pagamento antecipado']::text[], 2, 'medio', 'A dívida cresce sobre ela mesma. Quanto mais tempo passa sem pagar, maior fica a base de cálculo dos juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m15', 'juros-compostos-1-quiz', 'Os juros simples de 2% ao mês sobre R$ 500,00 rendem quanto em 1 ano?', array['R$ 120,00', 'R$ 10,00', 'R$ 60,00', 'R$ 134,12']::text[], 0, 'medio', 'Por mês: R$ 500,00 × 2% = R$ 10,00. Em 12 meses: R$ 120,00. A juros compostos seriam R$ 134,12.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-m16', 'juros-compostos-1-quiz', 'Gabriela aplicou R$ 4.000,00 a juros compostos de 1% ao mês. Depois de 2 meses, qual é o saldo?', array['R$ 4.080,00', 'R$ 4.040,00', 'R$ 4.080,40', 'R$ 4.100,00']::text[], 2, 'medio', 'Mês 1: R$ 4.000,00 × 1,01 = R$ 4.040,00. Mês 2: R$ 4.040,00 × 1,01 = R$ 4.080,40. Os R$ 4.080,00 seriam o resultado de juros simples.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-d1', 'juros-compostos-1-quiz', 'R$ 1.000,00 rendem 10% ao ano. Em 3 anos, quanto o montante a juros compostos supera o de juros simples?', array['R$ 10,00', 'R$ 100,00', 'R$ 300,00', 'R$ 31,00']::text[], 3, 'dificil', 'Simples: R$ 1.300,00. Compostos: R$ 1.331,00. A diferença é de R$ 31,00, que vem dos juros sobre juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-d2', 'juros-compostos-1-quiz', 'Um saldo aplicado a 10% ao mês, a juros compostos, chegou a R$ 1.210,00 depois de 2 meses. Qual foi o valor inicial?', array['R$ 1.000,00', 'R$ 1.100,00', 'R$ 1.008,33', 'R$ 1.200,00']::text[], 0, 'dificil', 'O saldo foi multiplicado duas vezes por 1,10, ou seja, por 1,21. Então o valor inicial foi R$ 1.210,00 ÷ 1,21 = R$ 1.000,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-1-d3', 'juros-compostos-1-quiz', 'Com juros compostos de 10% ao mês, em quantos meses R$ 1.000,00 passam de R$ 2.000,00?', array['7 meses', '8 meses', '10 meses', '12 meses']::text[], 1, 'dificil', 'Em 7 meses o saldo é R$ 1.948,72, ainda abaixo de R$ 2.000,00. Em 8 meses chega a R$ 2.143,59. Com juros simples seriam necessários 10 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f2', 'juros-compostos-2-quiz', 'O que é aporte?', array['A taxa que o banco cobra por mês', 'O valor que você retira todo mês', 'O imposto cobrado sobre o rendimento', 'O dinheiro novo que você coloca na aplicação']::text[], 3, 'facil', 'Aporte é o dinheiro novo que você coloca na aplicação, por exemplo todo mês. Aportes regulares ajudam os juros compostos a funcionar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f3', 'juros-compostos-2-quiz', 'Você aplica R$ 1.000,00 e, no fim, tem R$ 1.150,00. O que são os R$ 150,00?', array['O aporte', 'Os juros recebidos', 'O montante', 'A inflação do período']::text[], 1, 'facil', 'O montante é o valor final (R$ 1.150,00). Subtraindo o que foi investido (R$ 1.000,00), sobram R$ 150,00 de juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f4', 'juros-compostos-2-quiz', 'Por que começar a investir cedo costuma valer a pena?', array['Porque a taxa de juros é maior para quem é jovem', 'Porque o banco devolve os aportes depois de um tempo', 'Porque o dinheiro tem mais meses para render juros sobre juros', 'Porque o imposto desaparece com o tempo']::text[], 2, 'facil', 'O tempo é o ingrediente dos juros compostos. Quanto mais cedo se começa, mais meses de juros sobre juros se acumulam.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f5', 'juros-compostos-2-quiz', 'Qual hábito ajuda mais os juros compostos a trabalharem a seu favor?', array['Fazer aportes regulares e deixar o tempo passar', 'Resgatar o dinheiro todo mês', 'Mudar de aplicação toda semana', 'Aplicar uma única vez e nunca mais olhar']::text[], 0, 'facil', 'Aportar com regularidade e dar tempo ao dinheiro é a combinação que mais faz o saldo crescer.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-f6', 'juros-compostos-2-quiz', 'Mantendo a taxa e o prazo, o que acontece com o montante se o aporte mensal aumenta?', array['O montante cresce', 'O montante diminui', 'O montante fica igual', 'O montante vira zero']::text[], 0, 'facil', 'Aportes maiores colocam mais dinheiro para render, então o montante final é maior.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m3', 'juros-compostos-2-quiz', 'Você aporta R$ 200,00 por mês, no fim de cada mês, a 1% ao mês. Quanto tem depois de 6 meses?', array['R$ 1.200,00', 'R$ 1.260,00', 'R$ 1.230,40', 'R$ 1.300,00']::text[], 2, 'medio', 'R$ 200,00 × ((1,01⁶ − 1) ÷ 0,01) = R$ 1.230,40. Foram investidos R$ 1.200,00, e o resto são juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m4', 'juros-compostos-2-quiz', 'Com taxa zero, aportando R$ 150,00 por mês durante 12 meses, quanto se tem no final?', array['R$ 150,00', 'R$ 1.800,00', 'R$ 900,00', 'R$ 1.650,00']::text[], 1, 'medio', 'Sem rendimento, o saldo é só a soma dos aportes: R$ 150,00 × 12 = R$ 1.800,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m5', 'juros-compostos-2-quiz', 'Aportando R$ 100,00 por mês durante 5 anos, quanto você terá colocado do próprio bolso?', array['R$ 500,00', 'R$ 1.200,00', 'R$ 600,00', 'R$ 6.000,00']::text[], 3, 'medio', '5 anos são 60 meses: R$ 100,00 × 60 = R$ 6.000,00. O montante é maior, porque inclui também os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m6', 'juros-compostos-2-quiz', 'Aportes de R$ 300,00 por mês durante 36 meses, a 1% ao mês, formam R$ 12.923,06. Quanto desse total são juros?', array['R$ 12.923,06', 'R$ 2.123,06', 'R$ 10.800,00', 'R$ 1.292,31']::text[], 1, 'medio', 'Foram investidos R$ 10.800,00. Juros = R$ 12.923,06 − R$ 10.800,00 = R$ 2.123,06.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m7', 'juros-compostos-2-quiz', 'Você começa com R$ 2.000,00 e aporta R$ 100,00 por mês, a 1% ao mês, durante 12 meses. Qual é o montante?', array['R$ 3.521,90', 'R$ 3.200,00', 'R$ 3.400,00', 'R$ 3.600,00']::text[], 0, 'medio', 'Os R$ 2.000,00 iniciais viram R$ 2.253,65 e os aportes somam R$ 1.268,25. Juntos: R$ 3.521,90.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m8', 'juros-compostos-2-quiz', 'Ana aporta R$ 100,00 por mês durante 24 meses. Bia aporta R$ 200,00 por mês durante 12 meses. Com a mesma taxa, quem acumula mais?', array['Bia, porque os aportes dela são maiores', 'As duas acumulam exatamente o mesmo', 'Não dá para saber sem conhecer o banco', 'Ana, porque os aportes rendem por mais tempo']::text[], 3, 'medio', 'As duas investem R$ 2.400,00, mas, a 1% ao mês, Ana chega a R$ 2.697,35 e Bia, a R$ 2.536,50. O tempo vale mais do que o tamanho do aporte.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m9', 'juros-compostos-2-quiz', 'Com aportes de R$ 200,00 por mês e sem rendimento, em quantos meses se juntam R$ 6.000,00?', array['20 meses', '24 meses', '30 meses', '36 meses']::text[], 2, 'medio', 'R$ 6.000,00 ÷ R$ 200,00 = 30 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m10', 'juros-compostos-2-quiz', 'Aportes de R$ 100,00 por mês, a 1% ao mês, durante 36 meses ou durante 24 meses. Quanto o primeiro plano rende a mais?', array['R$ 1.200,00', 'R$ 1.000,00', 'R$ 1.610,34', 'R$ 2.000,00']::text[], 2, 'medio', '36 meses: R$ 4.307,69. 24 meses: R$ 2.697,35. A diferença é maior do que os R$ 1.200,00 dos 12 aportes extras, porque o tempo também rende.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m11', 'juros-compostos-2-quiz', 'Um plano investe R$ 1.200,00 de uma vez, hoje. Outro aporta R$ 100,00 por mês durante 12 meses. Com a mesma taxa, qual termina com mais dinheiro?', array['O dos R$ 1.200,00 de uma vez, que rende por mais tempo', 'O de aportes mensais, porque a regularidade rende mais', 'Os dois terminam com exatamente o mesmo valor', 'Nenhum dos dois rende juros']::text[], 0, 'medio', 'A 1% ao mês: R$ 1.352,19 contra R$ 1.268,25. Quando todo o dinheiro está disponível desde o início, ele rende por mais tempo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m12', 'juros-compostos-2-quiz', 'Mantidos os aportes e o prazo, o que acontece com o montante se a taxa mensal for maior?', array['Ele diminui, porque os juros pesam', 'Ele cresce, pois os juros são maiores', 'Ele fica igual, pois só o aporte importa', 'Ele zera no fim do prazo']::text[], 1, 'medio', 'Uma taxa maior significa mais juros sobre o saldo a cada mês, e o montante final aumenta.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m13', 'juros-compostos-2-quiz', 'Aportes de R$ 120,00 por mês durante 3 anos: quanto a pessoa investiu do próprio bolso?', array['R$ 360,00', 'R$ 1.440,00', 'R$ 3.600,00', 'R$ 4.320,00']::text[], 3, 'medio', '3 anos são 36 meses: R$ 120,00 × 36 = R$ 4.320,00. O montante é maior porque inclui os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-m14', 'juros-compostos-2-quiz', 'Quando o aporte é feito no fim de cada mês, o aporte do último mês rende juros?', array['Sim, ele rende o mês inteiro', 'Sim, ele rende metade do mês', 'Não: ele entra no último dia do mês', 'Só se for maior que o primeiro']::text[], 2, 'medio', 'No cálculo com aporte no fim do mês, o último aporte entra no último dia e não rende. Cada aporte rende por menos meses que o anterior.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d2', 'juros-compostos-2-quiz', 'Aportando R$ 100,00 por mês durante 60 meses, a 1% ao mês, o montante é R$ 8.166,97. Se o aporte passar para R$ 200,00, qual é o montante?', array['R$ 14.166,97', 'R$ 12.000,00', 'R$ 18.166,97', 'R$ 16.333,93']::text[], 3, 'dificil', 'O montante é proporcional ao aporte. Dobrando o aporte, o montante dobra: R$ 8.166,97 × 2 = R$ 16.333,93.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d3', 'juros-compostos-2-quiz', 'Aportes de R$ 250,00 por mês durante 48 meses, a 1% ao mês, chegam a R$ 15.305,65. Quanto são os juros?', array['R$ 12.000,00', 'R$ 3.305,65', 'R$ 15.305,65', 'R$ 1.530,57']::text[], 1, 'dificil', 'Foram investidos R$ 12.000,00. Os juros são R$ 15.305,65 − R$ 12.000,00 = R$ 3.305,65.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d4', 'juros-compostos-2-quiz', 'Com aportes de R$ 500,00 por mês, a 1% ao mês, em quantos meses completos se chega a R$ 10.000,00 ou mais?', array['19 meses', '18 meses', '20 meses', '24 meses']::text[], 0, 'dificil', 'Em 18 meses: R$ 9.807,37, ainda abaixo. Em 19 meses: R$ 10.405,45. Sem juros, seriam 20 meses.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d5', 'juros-compostos-2-quiz', 'Quem rende mais em 24 meses, a 1% ao mês: R$ 5.000,00 aplicados de uma vez ou aportes de R$ 200,00 por mês?', array['Os aportes mensais: R$ 5.394,69 contra R$ 6.348,67', 'Rendem exatamente o mesmo valor final', 'Não dá para comparar os dois planos', 'Os R$ 5.000,00 de uma vez: R$ 6.348,67 contra R$ 5.394,69']::text[], 3, 'dificil', 'O valor inicial rende por 24 meses, enquanto cada aporte rende por menos tempo. O valor inicial maior vence: R$ 6.348,67.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d6', 'juros-compostos-2-quiz', 'Um aporte de R$ 100,00 feito no fim do 1º mês fica rendendo até o fim do 12º mês, a 1% ao mês. Quanto ele vale no fim do 12º mês?', array['R$ 112,68', 'R$ 110,00', 'R$ 111,57', 'R$ 100,00']::text[], 2, 'dificil', 'Ele rende por 11 meses (do fim do mês 1 ao fim do mês 12): R$ 100,00 × 1,01¹¹ = R$ 111,57.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d7', 'juros-compostos-2-quiz', 'R$ 1.000,00 ficam aplicados a 1% ao mês. Quanto o saldo é maior depois de 24 meses do que depois de 12 meses?', array['R$ 142,91', 'R$ 126,83', 'R$ 253,65', 'R$ 269,73']::text[], 0, 'dificil', '12 meses: R$ 1.126,83. 24 meses: R$ 1.269,73. A diferença é maior que os juros do primeiro ano, porque o segundo ano rende sobre um saldo maior.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-2-d8', 'juros-compostos-2-quiz', 'Plano X: aporte de R$ 150,00 por mês por 24 meses. Plano Y: R$ 100,00 por mês nos primeiros 12 meses e R$ 200,00 nos últimos 12. Os dois investem R$ 3.600,00. A 1% ao mês, qual termina com mais?', array['Y, com R$ 3.965,60 contra R$ 4.046,02', 'X, com R$ 4.046,02 contra R$ 3.965,60', 'Os dois terminam com R$ 3.600,00', 'Não dá para comparar']::text[], 1, 'dificil', 'No plano X os aportes são iguais. No Y, os aportes maiores vêm no fim e rendem por menos tempo. Com o mesmo total investido, o dinheiro que entra mais cedo rende mais.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f2', 'juros-compostos-3-quiz', 'Por que não dá para comparar uma taxa ao mês com uma taxa ao ano sem converter?', array['Porque são de períodos diferentes', 'Porque a taxa ao ano é sempre maior', 'Porque a taxa ao mês não é válida', 'Porque o banco muda uma delas']::text[], 0, 'facil', 'Uma taxa ao mês e outra ao ano falam de períodos diferentes. Para comparar, é preciso converter uma delas pela equivalência.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f3', 'juros-compostos-3-quiz', 'O que é renda fixa?', array['Aplicação que nunca pode perder valor', 'Aplicação que só existe em bancos grandes', 'Aplicação com regras de rendimento conhecidas', 'Aplicação que rende o mesmo para todo mundo']::text[], 2, 'facil', 'Na renda fixa as regras do rendimento, como a taxa ou o indexador, são conhecidas no momento da aplicação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f4', 'juros-compostos-3-quiz', 'Para que serve converter taxas pela equivalência?', array['Para aumentar o rendimento da aplicação', 'Para pagar menos imposto sobre o ganho', 'Para evitar o efeito da inflação', 'Para comparar taxas de períodos diferentes']::text[], 3, 'facil', 'A equivalência traz as taxas para o mesmo período, e só assim a comparação é justa.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f5', 'juros-compostos-3-quiz', 'Como achar a taxa mensal a partir de uma taxa anual, com juros compostos?', array['Dividindo a taxa anual por 12', 'Usando a equivalência de taxas', 'Multiplicando a taxa anual por 12', 'Usando a taxa anual sem converter']::text[], 1, 'facil', 'A taxa mensal equivalente é aquela que, composta por 12 meses, resulta na taxa anual. Dividir por 12 não funciona.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-f6', 'juros-compostos-3-quiz', 'Uma aplicação rende 1% ao mês. A taxa anual equivalente é:', array['Exatamente 12%, porque 1 × 12 = 12', 'Maior que 12%, por juros sobre juros', 'Menor que 12%, por causa do desconto', 'Igual a 1%, a mesma taxa do mês']::text[], 1, 'facil', 'Como os juros são compostos, 1% ao mês equivale a cerca de 12,68% ao ano, e não a 12%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m2', 'juros-compostos-3-quiz', 'Uma taxa de 5% ao ano equivale a qual taxa mensal, aproximadamente?', array['0,42%', '0,50%', '0,41%', '0,05%']::text[], 2, 'medio', 'A equivalência é (1,05)^(1/12) − 1 = 0,4074%. Dividir 5% por 12 daria 0,4167%, que está errado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m3', 'juros-compostos-3-quiz', 'Uma taxa de 3% ao mês equivale a qual taxa anual, aproximadamente?', array['42,58%', '36,00%', '30,00%', '3,00%']::text[], 0, 'medio', '(1,03)¹² − 1 = 42,58%. Multiplicar por 12 daria 36%, e isso desconsideraria os juros sobre juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m4', 'juros-compostos-3-quiz', 'Uma taxa de 8% ao ano equivale a qual taxa mensal, aproximadamente?', array['0,67%', '0,80%', '0,08%', '0,64%']::text[], 3, 'medio', '(1,08)^(1/12) − 1 = 0,6434%, e não 8 ÷ 12 = 0,6667%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m5', 'juros-compostos-3-quiz', 'Uma taxa de 0,5% ao mês equivale a qual taxa anual, aproximadamente?', array['6,00%', '5,00%', '6,17%', '6,50%']::text[], 2, 'medio', '(1,005)¹² − 1 = 6,17%. É um pouco mais que os 6% de 0,5 × 12.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m6', 'juros-compostos-3-quiz', 'Um investimento paga 1,2% ao mês e outro, 14% ao ano. Qual rende mais?', array['O de 1,2% ao mês, cerca de 15,39% ao ano', 'O de 14% ao ano, porque 14 é maior que 1,2', 'Rendem exatamente o mesmo por ano', 'Não dá para comparar as duas taxas']::text[], 0, 'medio', 'Convertendo, 1,2% ao mês equivale a 15,39% ao ano, acima dos 14%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m7', 'juros-compostos-3-quiz', 'Alguém divide 24% ao ano por 12 e diz que a taxa mensal é 2%. Qual é o erro?', array['Não há erro: dividir por 12 sempre funciona', 'A taxa mensal correta é 2,5%', 'A taxa mensal correta é 24%', 'Ignorar os juros sobre juros: o correto é 1,81%']::text[], 3, 'medio', 'A taxa mensal equivalente a 24% ao ano é (1,24)^(1/12) − 1 = 1,81%. Dividir por 12 só vale para juros simples.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m8', 'juros-compostos-3-quiz', 'R$ 1.000,00 rendem 12% ao ano, a juros compostos. Depois de 1 ano, o saldo é:', array['R$ 1.126,83', 'R$ 1.120,00', 'R$ 1.012,00', 'R$ 1.200,00']::text[], 1, 'medio', 'Em 1 ano, a taxa anual já é a própria taxa do período: R$ 1.000,00 × 1,12 = R$ 1.120,00. Os R$ 1.126,83 seriam de 1% ao mês, que equivale a 12,68% ao ano.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m9', 'juros-compostos-3-quiz', 'Qual destas é mais claramente uma aplicação de renda fixa?', array['Uma ação de uma empresa de capital aberto', 'Um bilhete de loteria da semana', 'Dólares guardados em casa, sem aplicar', 'Um título com taxa informada na compra']::text[], 3, 'medio', 'Na renda fixa as regras do rendimento são conhecidas na hora da aplicação, e é isso que a diferencia das demais aplicações.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m10', 'juros-compostos-3-quiz', 'Qual é a taxa mensal equivalente a 18% ao ano?', array['1,39%', '1,50%', '1,80%', '0,15%']::text[], 0, 'medio', '(1,18)^(1/12) − 1 = 1,39%. Dividir 18% por 12 daria 1,50%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m11', 'juros-compostos-3-quiz', 'Uma aplicação rende 1% ao mês. Qual é a taxa acumulada em 2 meses?', array['2,00%', '2,01%', '2,10%', '1,00%']::text[], 1, 'medio', '(1,01)² − 1 = 2,01%. É um pouco mais que 2%, por causa dos juros sobre juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-m12', 'juros-compostos-3-quiz', 'Uma taxa de 0,8% ao mês equivale a qual taxa anual, aproximadamente?', array['9,60%', '8,00%', '10,03%', '12,00%']::text[], 2, 'medio', '(1,008)¹² − 1 = 10,03%. Multiplicar 0,8 por 12 daria 9,6%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d3', 'juros-compostos-3-quiz', 'Uma aplicação rende 15% ao ano. Qual é o rendimento equivalente em 6 meses?', array['7,50%', '7,00%', '6,00%', '7,24%']::text[], 3, 'dificil', 'Para meio ano, (1,15)^(1/2) − 1 = 7,24%. Dividir 15% por 2 daria 7,50%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d4', 'juros-compostos-3-quiz', 'Uma aplicação rende 0,9% ao mês e outra, 11% ao ano. Qual afirmação está correta?', array['A segunda rende mais, porque 11% é maior que 0,9%', 'Rendem exatamente igual', 'A primeira rende mais: 11,35% ao ano contra 11%', 'A primeira rende menos, porque a taxa é pequena']::text[], 2, 'dificil', '(1,009)¹² − 1 = 11,35%, acima dos 11%. Só dá para comparar depois de converter para o mesmo período.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d5', 'juros-compostos-3-quiz', 'R$ 2.000,00 rendem 10% ao ano, e o resultado foi calculado pela taxa equivalente. Qual é o saldo depois de 6 meses?', array['R$ 2.100,00', 'R$ 2.097,62', 'R$ 2.095,00', 'R$ 2.200,00']::text[], 1, 'dificil', 'Em 6 meses, o fator é (1,10)^(1/2) = 1,0488. R$ 2.000,00 × 1,0488 = R$ 2.097,62.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d6', 'juros-compostos-3-quiz', 'Uma taxa de 3% ao trimestre equivale a qual taxa anual?', array['12,55%', '12,00%', '9,00%', '3,00%']::text[], 0, 'dificil', 'São 4 trimestres no ano: (1,03)⁴ − 1 = 12,55%. A conversão por equivalência funciona para qualquer período.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d7', 'juros-compostos-3-quiz', 'Qual é a taxa mensal equivalente a 21% ao ano?', array['1,60%', '1,75%', '1,50%', '2,00%']::text[], 0, 'dificil', '(1,21)^(1/12) − 1 = 1,60%. Dividir por 12 daria 1,75%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d8', 'juros-compostos-3-quiz', 'Qual é a taxa anual equivalente a 1,5% ao mês?', array['18,00%', '19,00%', '20,00%', '19,56%']::text[], 3, 'dificil', '(1,015)¹² − 1 = 19,56%. Os 18% de 1,5 × 12 ficam abaixo do valor correto.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d9', 'juros-compostos-3-quiz', 'Qual cálculo converte corretamente 6% ao ano em taxa mensal?', array['Dividir 6% por 12', 'Elevar 1,06 a 1/12 e subtrair 1', 'Multiplicar 6% por 12', 'Somar 6% a 12 e dividir por dois']::text[], 1, 'dificil', 'A taxa mensal equivalente é a raiz 12ª do fator anual, menos 1. Dividir por 12 só vale para juros simples.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('juros-compostos-3-d10', 'juros-compostos-3-quiz', 'Uma aplicação paga 0,7% ao mês e outra, 8,5% ao ano. Qual rende mais?', array['A segunda, porque 8,5% é maior que 0,7%', 'Rendem exatamente igual', 'A primeira, que equivale a cerca de 8,73% ao ano', 'A segunda, porque a taxa anual sempre rende mais']::text[], 2, 'dificil', '(1,007)¹² − 1 = 8,73%, acima dos 8,5% da outra aplicação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f2', 'cartao-de-credito-1-quiz', 'O que é o limite do cartão?', array['O valor máximo liberado pelo banco', 'O dia em que a fatura vence', 'A taxa de juros do cartão', 'O menor valor que deve ser pago']::text[], 0, 'facil', 'O limite é o teto de gastos liberado pelo banco. Ele diminui conforme você compra e volta quando você paga a fatura.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f3', 'cartao-de-credito-1-quiz', 'O que é o vencimento da fatura?', array['O dia em que a fatura "vira"', 'O dia da compra', 'A data-limite para pagar', 'O valor do limite']::text[], 2, 'facil', 'Vencimento é o prazo de pagamento. O dia em que a fatura "vira" é o fechamento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f4', 'cartao-de-credito-1-quiz', 'Se você paga o valor total da fatura até o vencimento, o que acontece com os juros?', array['Os juros dobram', 'O limite diminui', 'A fatura seguinte fica maior', 'Não há juros']::text[], 3, 'facil', 'Pagar o total até o vencimento evita juros. Nesse caso, o cartão é só uma conveniência.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f5', 'cartao-de-credito-1-quiz', 'O que a fatura do cartão mostra?', array['Só o seu saldo bancário', 'As compras de um período e quanto você deve pagar', 'As compras de todos os clientes do banco', 'O rendimento das suas aplicações']::text[], 1, 'facil', 'A fatura reúne as compras do período e informa o valor a pagar e a data de vencimento.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f6', 'cartao-de-credito-1-quiz', 'Qual pergunta ajuda antes de comprar no cartão?', array['"Qual é a cor do cartão?"', '"Eu consigo pagar a fatura inteira?"', '"Quantas lojas aceitam esse cartão?"', '"O banco pode aumentar o meu limite?"']::text[], 1, 'facil', 'Se a resposta for não, a compra pode custar bem mais do que o preço, porque o restante vira dívida com juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f7', 'cartao-de-credito-1-quiz', 'O que acontece com o limite quando você faz uma compra no cartão?', array['Ele aumenta no mesmo valor', 'Nada, o limite é sempre o mesmo', 'Ele diminui até a fatura ser paga', 'Ele zera assim que a compra é feita']::text[], 2, 'facil', 'O limite disponível é o limite total menos o que você já gastou e ainda não pagou.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f8', 'cartao-de-credito-1-quiz', 'O que é o cartão de crédito?', array['Uma forma de comprar agora e pagar depois', 'Uma conta que rende juros todo mês', 'Dinheiro que o banco dá de graça', 'Uma aplicação que paga juros ao cliente']::text[], 0, 'facil', 'O cartão de crédito adianta a compra e o pagamento vem na fatura. Se não for pago em dia, vira dívida.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-f9', 'cartao-de-credito-1-quiz', 'Qual destas é uma boa prática com o cartão de crédito?', array['Pagar sempre só o mínimo', 'Usar todo o limite todo mês', 'Parcelar toda compra pequena', 'Pagar o total da fatura todo mês']::text[], 3, 'facil', 'Pagar o total evita juros. Usar todo o limite e pagar só o mínimo tornam a dívida difícil de controlar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m4', 'cartao-de-credito-1-quiz', 'Em um mês, Lia comprou no mercado (R$ 420,00), na farmácia (R$ 85,50) e num aplicativo de transporte (R$ 63,50). Qual será o valor da fatura?', array['R$ 505,50', 'R$ 483,50', 'R$ 569,00', 'R$ 149,00']::text[], 2, 'medio', 'A fatura soma as compras do período: R$ 420,00 + R$ 85,50 + R$ 63,50 = R$ 569,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m5', 'cartao-de-credito-1-quiz', 'O limite é R$ 4.000,00 e a fatura aberta é de R$ 1.350,00. Quanto resta de limite disponível?', array['R$ 2.650,00', 'R$ 1.350,00', 'R$ 4.000,00', 'R$ 5.350,00']::text[], 0, 'medio', 'O limite disponível é o total menos o que já foi usado: R$ 4.000,00 − R$ 1.350,00 = R$ 2.650,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m6', 'cartao-de-credito-1-quiz', 'Carlos fez compras de R$ 180,00, R$ 95,00 e R$ 60,00 antes do fechamento. Qual será o valor da fatura?', array['R$ 275,00', 'R$ 240,00', 'R$ 155,00', 'R$ 335,00']::text[], 3, 'medio', 'A fatura soma as compras do período: R$ 180,00 + R$ 95,00 + R$ 60,00 = R$ 335,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m7', 'cartao-de-credito-1-quiz', 'O fechamento é no dia 10. Uma compra feita no dia 8 e outra feita no dia 12 entram:', array['As duas na fatura atual', 'A do dia 8 na fatura atual e a do dia 12 na seguinte', 'As duas na fatura seguinte', 'A do dia 8 na seguinte e a do dia 12 na atual']::text[], 1, 'medio', 'Compras feitas até o fechamento entram na fatura atual. As feitas depois entram na fatura seguinte.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m8', 'cartao-de-credito-1-quiz', 'A fatura de R$ 950,00 foi paga integralmente no vencimento. Quanto foi cobrado de juros?', array['R$ 95,00', 'R$ 47,50', 'R$ 950,00', 'R$ 0,00']::text[], 3, 'medio', 'Pagando o total até o vencimento não há juros. O cartão só custa mais quando parte da fatura fica em aberto.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m9', 'cartao-de-credito-1-quiz', 'O limite de um cartão é R$ 2.500,00. Depois de uma compra de R$ 1.800,00 e do pagamento da fatura, como fica o limite?', array['Volta a R$ 2.500,00', 'Fica em R$ 700,00', 'Dobra para R$ 5.000,00', 'Fica zerado']::text[], 0, 'medio', 'O limite é recomposto à medida que a fatura é paga. Pagando o total, ele volta ao valor original.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m10', 'cartao-de-credito-1-quiz', 'Camila usa 90% de um limite de R$ 1.800,00. Quanto ela já gastou?', array['R$ 180,00', 'R$ 1.620,00', 'R$ 1.800,00', 'R$ 900,00']::text[], 1, 'medio', 'R$ 1.800,00 × 0,90 = R$ 1.620,00. Sobram R$ 180,00 de limite.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m11', 'cartao-de-credito-1-quiz', 'Qual é a diferença entre fechamento e vencimento?', array['O fechamento é o prazo para pagar; o vencimento define as compras', 'São o mesmo dia, com nomes diferentes', 'O fechamento define as compras da fatura; o vencimento é o prazo', 'O fechamento é quando o limite aumenta']::text[], 2, 'medio', 'Fechamento: o dia em que a fatura "vira". Vencimento: a data-limite para pagá-la.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m12', 'cartao-de-credito-1-quiz', 'A fatura venceu e não foi paga. O que acontece com o valor em aberto?', array['Some, porque o prazo acabou', 'É perdoado depois de 30 dias', 'Passa a render para o cliente', 'Vira dívida e passa a ter juros']::text[], 3, 'medio', 'O valor não pago continua sendo dívida, e os juros começam a ser cobrados sobre ele.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m13', 'cartao-de-credito-1-quiz', 'João pagou R$ 480,00 de uma fatura em dia. No mês seguinte, comprou R$ 300,00 antes do fechamento. De quanto será a próxima fatura?', array['R$ 780,00', 'R$ 480,00', 'R$ 300,00', 'R$ 180,00']::text[], 2, 'medio', 'A fatura anterior foi paga, então só as novas compras contam: R$ 300,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m14', 'cartao-de-credito-1-quiz', 'A fatura média de uma pessoa é R$ 1.100,00 e a renda é R$ 2.200,00. Que parte da renda a fatura consome?', array['25%', '50%', '40%', '100%']::text[], 1, 'medio', 'R$ 1.100,00 ÷ R$ 2.200,00 = 0,50, ou seja, 50% da renda. Acompanhar esse peso ajuda a não passar do que dá para pagar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m15', 'cartao-de-credito-1-quiz', 'Laura tem limite de R$ 5.000,00 e já usou R$ 3.250,00. Que percentual do limite está em uso?', array['65%', '35%', '75%', '32,5%']::text[], 0, 'medio', 'R$ 3.250,00 ÷ R$ 5.000,00 = 0,65, ou 65%. Sobram 35% do limite.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-m16', 'cartao-de-credito-1-quiz', 'Qual é uma boa forma de não esquecer o vencimento da fatura?', array['Programar um lembrete ou o pagamento automático', 'Pagar sempre alguns dias depois do vencimento', 'Esperar o banco avisar por telefone', 'Pagar só quando o limite acabar']::text[], 0, 'medio', 'Pagar em dia evita juros e multa. Lembretes e pagamento automático do valor total ajudam a não esquecer.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-d1', 'cartao-de-credito-1-quiz', 'O limite é R$ 3.000,00. Você usou R$ 1.450,00 e depois fez uma compra de R$ 1.200,00. Quanto de limite ainda está disponível?', array['R$ 1.550,00', 'R$ 1.800,00', 'R$ 2.650,00', 'R$ 350,00']::text[], 3, 'dificil', 'Já foram usados R$ 1.450,00 + R$ 1.200,00 = R$ 2.650,00. Do limite de R$ 3.000,00 sobram R$ 350,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-d2', 'cartao-de-credito-1-quiz', 'Uma fatura de R$ 2.000,00 foi paga com R$ 1.700,00 no vencimento. O que se pode dizer?', array['Ficaram R$ 1.700,00 em aberto e o limite livre é R$ 300,00', 'Ficaram R$ 300,00 em aberto e o limite livre voltou a R$ 1.700,00', 'Nada ficou em aberto e o limite voltou a R$ 2.000,00', 'Ficaram R$ 300,00 em aberto e o limite livre voltou a R$ 2.000,00']::text[], 1, 'dificil', 'Em aberto: R$ 2.000,00 − R$ 1.700,00 = R$ 300,00. O limite livre recompõe só o valor pago, R$ 1.700,00. A parte em aberto segue ocupando o limite e gerando juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-1-d3', 'cartao-de-credito-1-quiz', 'A fatura de R$ 2.400,00 é paga integralmente em dia, mas uma compra de R$ 600,00 é feita 2 dias depois do fechamento. O que acontece?', array['A compra entra na fatura atual, que passa a ser de R$ 3.000,00', 'A compra gera juros imediatamente', 'A compra de R$ 600,00 entra na fatura seguinte, sem juros na atual', 'O pagamento fica incompleto e cai no rotativo']::text[], 2, 'dificil', 'Compras depois do fechamento vão para a fatura seguinte. A fatura atual, paga por inteiro, não gera juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f2', 'cartao-de-credito-2-quiz', 'O que é o pagamento mínimo da fatura?', array['O valor máximo que o banco permite pagar', 'O menor valor para manter a fatura em dia', 'O valor dos juros cobrados no mês', 'O preço da compra mais barata da fatura']::text[], 1, 'facil', 'O mínimo mantém a fatura em dia, mas o que não foi pago continua sendo dívida, com juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f3', 'cartao-de-credito-2-quiz', 'O que é o crédito rotativo?', array['Um prêmio dado a quem paga em dia', 'Um desconto automático na fatura', 'Crédito da parte não paga, com juros altos', 'Um limite extra, gratuito e sem juros']::text[], 2, 'facil', 'O rotativo é a modalidade em que o saldo não pago fica rendendo juros, entre os mais altos do mercado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f4', 'cartao-de-credito-2-quiz', 'Pagar só o mínimo resolve a dívida?', array['Sim, a fatura é zerada na hora', 'Sim, mas só no mês seguinte', 'Sim, e o banco devolve os juros', 'Não: o resto continua como dívida']::text[], 3, 'facil', 'O pagamento mínimo alivia o mês, mas o saldo que sobra continua sendo dívida com juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f5', 'cartao-de-credito-2-quiz', 'Como costumam ser os juros do crédito rotativo?', array['Altos, entre os maiores do mercado', 'Baixos, como os da poupança', 'Zerados durante o primeiro mês', 'Iguais à inflação do período']::text[], 0, 'facil', 'Os juros do rotativo costumam ser de vários por cento ao mês. Em pouco tempo, a dívida cresce bem mais do que a compra original.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-f6', 'cartao-de-credito-2-quiz', 'Pelas regras atuais, por quanto tempo o saldo pode ficar no rotativo?', array['Por até 12 meses seguidos', 'Para sempre, sem limite de prazo', 'Só até a próxima fatura', 'Por até cinco anos']::text[], 2, 'facil', 'O rotativo dura só até a próxima fatura. Depois disso, o saldo precisa ser parcelado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m3', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 1.400,00 teve pagamento mínimo de R$ 210,00. Quanto vai para o rotativo?', array['R$ 210,00', 'R$ 1.190,00', 'R$ 1.400,00', 'R$ 1.610,00']::text[], 1, 'medio', 'O saldo que fica em aberto é R$ 1.400,00 − R$ 210,00 = R$ 1.190,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m4', 'cartao-de-credito-2-quiz', 'R$ 700,00 ficam no rotativo a 12% ao mês. Quanto é de juros em 1 mês?', array['R$ 84,00', 'R$ 70,00', 'R$ 120,00', 'R$ 784,00']::text[], 0, 'medio', 'R$ 700,00 × 12% = R$ 84,00. O saldo passa a ser R$ 784,00: os R$ 784,00 incluem o valor devido e os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m5', 'cartao-de-credito-2-quiz', 'R$ 500,00 ficam no rotativo a 14% ao mês. Quanto o saldo vira depois de 1 mês?', array['R$ 514,00', 'R$ 550,00', 'R$ 640,00', 'R$ 570,00']::text[], 3, 'medio', 'R$ 500,00 × 1,14 = R$ 570,00: são R$ 70,00 de juros em um único mês.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m6', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 900,00 é paga com R$ 450,00. Quanto vai para o rotativo?', array['R$ 900,00', 'R$ 0,00', 'R$ 1.350,00', 'R$ 450,00']::text[], 3, 'medio', 'R$ 900,00 − R$ 450,00 = R$ 450,00 em aberto, que passam a render juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m7', 'cartao-de-credito-2-quiz', 'Por que não vale a pena pagar só o mínimo todo mês?', array['Porque o saldo restante gera juros altos', 'Porque o banco bloqueia o cartão no mesmo dia', 'Porque o mínimo é proibido por lei', 'Porque o limite do cartão aumenta sem parar']::text[], 0, 'medio', 'O mínimo adia o problema e deixa a dívida rendendo juros altos para o banco.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m8', 'cartao-de-credito-2-quiz', 'O pagamento mínimo é 15% da fatura de R$ 1.200,00. Qual é o valor mínimo?', array['R$ 15,00', 'R$ 1.020,00', 'R$ 180,00', 'R$ 300,00']::text[], 2, 'medio', 'R$ 1.200,00 × 0,15 = R$ 180,00. Os R$ 1.020,00 seriam o que fica no rotativo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m9', 'cartao-de-credito-2-quiz', 'R$ 1.200,00 no rotativo a 9% ao mês. Quanto é de juros em 1 mês?', array['R$ 9,00', 'R$ 108,00', 'R$ 120,00', 'R$ 1.308,00']::text[], 1, 'medio', 'R$ 1.200,00 × 9% = R$ 108,00. Em um mês, a dívida vai a R$ 1.308,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m10', 'cartao-de-credito-2-quiz', 'Quando não dá para pagar a fatura inteira, qual atitude é melhor?', array['Pagar o máximo possível e negociar o resto', 'Pagar só o mínimo e esquecer o resto', 'Deixar a fatura vencer sem pagar nada', 'Fazer novas compras para compensar']::text[], 0, 'medio', 'Quanto maior o pagamento, menor o saldo que rende juros altos. Comparar com outras formas de crédito mais baratas ajuda a quitar o restante.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m11', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 800,00 foi paga com R$ 200,00. Com juros de 10% ao mês no rotativo, o saldo na fatura seguinte será de:', array['R$ 610,00', 'R$ 660,00', 'R$ 600,00', 'R$ 680,00']::text[], 1, 'medio', 'O saldo em aberto é R$ 600,00. Com 10% de juros: R$ 600,00 × 1,10 = R$ 660,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m12', 'cartao-de-credito-2-quiz', 'Deixar R$ 900,00 no rotativo por 1 mês, a 12%, custa quanto de juros?', array['R$ 12,00', 'R$ 100,00', 'R$ 108,00', 'R$ 900,00']::text[], 2, 'medio', 'R$ 900,00 × 12% = R$ 108,00. Pagar o total evitaria todo esse custo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m13', 'cartao-de-credito-2-quiz', 'Qual afirmação sobre o pagamento mínimo está correta?', array['Quita a fatura por completo e zera o rotativo', 'Evita qualquer cobrança de juros sobre o saldo', 'Só vale para quem tem um limite bem alto', 'Mantém a fatura em dia, mas o resto vai ao rotativo']::text[], 3, 'medio', 'O mínimo evita o atraso, mas não a dívida: o que sobra passa a ter juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-m14', 'cartao-de-credito-2-quiz', 'Ao fechar a próxima fatura, o que acontece com o saldo que continuou sem pagamento no rotativo?', array['Precisa ser parcelado', 'Fica no rotativo para sempre', 'É apagado do sistema', 'Vira um bônus']::text[], 0, 'medio', 'O rotativo vale só até a próxima fatura. Depois, o saldo precisa ser parcelado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d2', 'cartao-de-credito-2-quiz', 'Fatura de R$ 2.500,00 com mínimo de 15%. O que restou rende 13% ao mês no rotativo. Quanto será esse saldo na fatura seguinte?', array['R$ 2.125,00', 'R$ 2.500,00', 'R$ 2.825,00', 'R$ 2.401,25']::text[], 3, 'dificil', 'Mínimo: R$ 375,00. Saldo: R$ 2.125,00. Com juros de 13%: R$ 2.125,00 × 1,13 = R$ 2.401,25. Os R$ 2.825,00 seriam o erro de aplicar juros sobre a fatura inteira.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d3', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 3.000,00 foi paga com R$ 600,00, e o rotativo cobra 12% ao mês. O saldo na fatura seguinte será de:', array['R$ 2.400,00', 'R$ 3.360,00', 'R$ 2.688,00', 'R$ 3.600,00']::text[], 2, 'dificil', 'Em aberto: R$ 2.400,00. Com juros de 12%: R$ 2.400,00 × 1,12 = R$ 2.688,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d4', 'cartao-de-credito-2-quiz', 'O rotativo cobra 10% ao mês. Se essa taxa se repetisse por 12 meses, a taxa anual equivalente seria de:', array['120,00%', '213,84%', '110,00%', '12,00%']::text[], 1, 'dificil', '(1,10)¹² − 1 = 213,84%. Por isso a lei limitou o rotativo a uma fatura: ele cresce rápido demais.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d5', 'cartao-de-credito-2-quiz', 'Para que sobrem no máximo R$ 1.350,00 no rotativo numa fatura de R$ 1.800,00, qual é o pagamento mínimo necessário?', array['R$ 1.350,00', 'R$ 450,00', 'R$ 1.800,00', 'R$ 900,00']::text[], 1, 'dificil', 'R$ 1.800,00 − R$ 1.350,00 = R$ 450,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d6', 'cartao-de-credito-2-quiz', 'Carla pagou R$ 400,00 de uma fatura de R$ 1.600,00. O rotativo cobra 11% ao mês. Quanto de juros ela paga no mês?', array['R$ 176,00', 'R$ 44,00', 'R$ 11,00', 'R$ 132,00']::text[], 3, 'dificil', 'O saldo é R$ 1.200,00. Juros: R$ 1.200,00 × 11% = R$ 132,00. Os R$ 176,00 seriam 11% sobre a fatura inteira, e os R$ 44,00, 11% sobre o valor pago.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d7', 'cartao-de-credito-2-quiz', 'A pessoa A paga o total de R$ 900,00. A pessoa B paga o mínimo de R$ 135,00 e deixa o resto no rotativo, a 10%. Na fatura seguinte, sem novas compras, quanto B deve a mais que A?', array['R$ 841,50', 'R$ 765,00', 'R$ 900,00', 'R$ 76,50']::text[], 0, 'dificil', 'Saldo de B: R$ 765,00. Com 10%: R$ 765,00 × 1,10 = R$ 841,50. A não deve nada.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-2-d8', 'cartao-de-credito-2-quiz', 'Uma fatura de R$ 1.250,00 deixou R$ 1.062,50 no rotativo. Que parte da fatura foi paga?', array['85%', '25%', '15%', '10%']::text[], 2, 'dificil', 'Foram pagos R$ 1.250,00 − R$ 1.062,50 = R$ 187,50. R$ 187,50 ÷ R$ 1.250,00 = 0,15, ou seja, 15%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f2', 'cartao-de-credito-3-quiz', 'Na tabela Price, como são as parcelas?', array['Crescem a cada mês', 'Diminuem a cada mês', 'Todas têm o mesmo valor', 'Dependem do dia do mês']::text[], 2, 'facil', 'Na tabela Price as parcelas são iguais, e os juros incidem sobre o saldo que ainda falta pagar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f3', 'cartao-de-credito-3-quiz', 'O que significa parcelar o saldo da fatura?', array['Apagar a dívida sem custo nenhum', 'Dividir o valor em parcelas iguais, com juros', 'Pagar tudo de uma vez só, sem juros', 'Trocar de cartão sem nenhum custo extra']::text[], 1, 'facil', 'O parcelamento divide o saldo em parcelas iguais. Como há juros, o total pago é maior que o saldo parcelado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f4', 'cartao-de-credito-3-quiz', 'Ao comparar ofertas de crédito, o que olhar além da taxa de juros?', array['A cor do papel do contrato', 'O nome do gerente da agência', 'O número impresso no cartão', 'O CET, o custo efetivo total']::text[], 3, 'facil', 'O CET reúne os juros, as tarifas e os impostos. Comparar só a taxa de juros pode enganar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f5', 'cartao-de-credito-3-quiz', 'Num parcelamento com juros, o total pago é:', array['Maior que o valor parcelado', 'Igual ao valor parcelado', 'Menor que o valor parcelado', 'Sempre o dobro do valor parcelado']::text[], 0, 'facil', 'Os juros são o custo do parcelamento. Por isso, a soma das parcelas é maior do que o saldo parcelado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-f6', 'cartao-de-credito-3-quiz', 'Por que olhar só a taxa de juros pode enganar?', array['Porque a taxa muda sozinha todo mês', 'Porque o banco é proibido de informar a taxa', 'Porque a taxa é igual em todos os bancos', 'Porque tarifas e impostos também entram no custo']::text[], 3, 'facil', 'O CET soma juros, tarifas e impostos. Ele mostra o custo real, e a taxa de juros mostra só uma parte.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m2', 'cartao-de-credito-3-quiz', 'R$ 1.000,00 parcelados em 6 vezes a 5% ao mês, pela tabela Price. Qual é o valor de cada parcela?', array['R$ 166,67', 'R$ 197,02', 'R$ 175,00', 'R$ 223,35']::text[], 1, 'medio', 'Parcela = R$ 1.000,00 × 0,05 ÷ (1 − 1,05⁻⁶) = R$ 197,02. Dividir o saldo por 6 ignora os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m3', 'cartao-de-credito-3-quiz', 'R$ 1.000,00 parcelados em 6 vezes de R$ 197,02. Quanto o total pago tem de juros?', array['R$ 182,12', 'R$ 50,00', 'R$ 300,00', 'R$ 1.182,12']::text[], 0, 'medio', 'Total pago: R$ 1.182,12. Juros: R$ 1.182,12 − R$ 1.000,00 = R$ 182,12.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m4', 'cartao-de-credito-3-quiz', 'Um saldo de R$ 800,00 foi parcelado em 4 vezes de R$ 230,00. Qual é o total pago?', array['R$ 230,00', 'R$ 800,00', 'R$ 920,00', 'R$ 1.000,00']::text[], 2, 'medio', 'R$ 230,00 × 4 = R$ 920,00, ou seja, R$ 120,00 acima do saldo parcelado.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m5', 'cartao-de-credito-3-quiz', 'Pelo teto legal, um saldo de R$ 600,00 em aberto pode gerar, no máximo, quanto pago no total (saldo mais juros)?', array['R$ 1.200,00', 'R$ 660,00', 'R$ 1.800,00', 'R$ 600,00']::text[], 0, 'medio', 'A soma dos juros do rotativo e do parcelamento não pode passar de 100% do valor em aberto. Então o total chega, no máximo, a R$ 600,00 + R$ 600,00 = R$ 1.200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m6', 'cartao-de-credito-3-quiz', 'Os juros somados de uma dívida em aberto de R$ 1.500,00 chegaram a R$ 1.500,00. O que acontece?', array['Os juros continuam sem nenhum limite legal', 'O teto legal foi atingido: os juros param aí', 'A dívida é perdoada pelo banco', 'A taxa dobra no mês seguinte, por lei']::text[], 1, 'medio', 'A lei limita a soma dos juros a 100% do valor que ficou em aberto. Ao chegar a esse valor, a cobrança de juros para.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m7', 'cartao-de-credito-3-quiz', 'Duas ofertas de crédito têm taxas diferentes e tarifas diferentes. Como compará-las?', array['Só pela menor taxa de juros', 'Pelo nome do banco', 'Pelo valor da primeira parcela', 'Pelo CET de cada uma']::text[], 3, 'medio', 'O CET traz os juros, as tarifas e os impostos num único número, o que permite comparar de verdade.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m8', 'cartao-de-credito-3-quiz', 'R$ 2.000,00 parcelados em 10 vezes a 4% ao mês, pela tabela Price. Qual é o valor de cada parcela?', array['R$ 200,00', 'R$ 208,00', 'R$ 246,58', 'R$ 280,00']::text[], 2, 'medio', 'Parcela = R$ 2.000,00 × 0,04 ÷ (1 − 1,04⁻¹⁰) = R$ 246,58. A parcela é maior que R$ 200,00, porque inclui os juros.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m9', 'cartao-de-credito-3-quiz', 'R$ 2.000,00 parcelados em 10 vezes de R$ 246,58. Quanto vai de juros?', array['R$ 246,58', 'R$ 465,80', 'R$ 2.465,80', 'R$ 80,00']::text[], 1, 'medio', 'Total pago: R$ 2.465,80. Juros: R$ 2.465,80 − R$ 2.000,00 = R$ 465,80.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m10', 'cartao-de-credito-3-quiz', 'Na tabela Price, a parcela é igual, mas a parte de juros muda ao longo do tempo. Como?', array['Os juros são maiores no começo, quando o saldo é maior', 'Os juros são maiores nas últimas parcelas', 'Os juros são iguais em todas as parcelas', 'Os juros só são cobrados na primeira parcela']::text[], 0, 'medio', 'Os juros incidem sobre o saldo que ainda falta pagar. No começo esse saldo é alto, e ele diminui a cada parcela paga.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m11', 'cartao-de-credito-3-quiz', 'Parcelar o mesmo saldo em 12 vezes, em vez de 6, à mesma taxa, resulta em:', array['Parcelas maiores e menos juros no total', 'Parcelas iguais e o mesmo total', 'Parcelas menores e mais juros no total', 'Nenhum juro, porque o prazo é maior']::text[], 2, 'medio', 'Mais parcelas diminuem o valor mensal, mas o dinheiro fica devendo por mais tempo, e o total de juros aumenta.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-m12', 'cartao-de-credito-3-quiz', 'Uma loja anuncia "parcelas que cabem no bolso", mas o CET é alto. O que fazer?', array['Fechar o negócio pela menor parcela', 'Ignorar o CET, porque ele só importa para empresas', 'Escolher o prazo mais longo possível', 'Comparar o CET e o total a pagar antes de decidir']::text[], 3, 'medio', 'A parcela pequena pode esconder um custo total alto. Compare o CET e o valor total a pagar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d3', 'cartao-de-credito-3-quiz', 'Um saldo de R$ 1.200,00 foi parcelado em 12 vezes de R$ 140,00. O teto legal foi atingido?', array['Sim, o teto já foi ultrapassado', 'Não: R$ 480,00 de juros, abaixo do teto', 'Sim, os juros somam R$ 1.680,00', 'Não existe teto legal para os juros']::text[], 1, 'dificil', 'Total pago: R$ 140,00 × 12 = R$ 1.680,00. Juros: R$ 1.680,00 − R$ 1.200,00 = R$ 480,00, menos que os R$ 1.200,00 permitidos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d4', 'cartao-de-credito-3-quiz', 'Um saldo de R$ 500,00 rendeu 15% de juros no rotativo e foi parcelado em 5 vezes de R$ 130,00. A soma dos juros respeita o teto legal?', array['Não: R$ 650,00 passam do teto', 'Sim, mas só porque o rotativo foi menor que R$ 75,00', 'Não, porque o teto é de 10%', 'Sim: R$ 150,00 são menos que os R$ 500,00 do teto']::text[], 3, 'dificil', 'Rotativo: R$ 500,00 × 15% = R$ 75,00, e o saldo vai a R$ 575,00. Parcelas: R$ 650,00, ou seja, mais R$ 75,00 de juros. Soma: R$ 150,00, bem abaixo dos R$ 500,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d5', 'cartao-de-credito-3-quiz', 'O teto legal vale para uma dívida de R$ 800,00 parcelada em 10 vezes. Qual é o maior valor de parcela que respeita o teto?', array['R$ 80,00', 'R$ 176,00', 'R$ 160,00', 'R$ 200,00']::text[], 2, 'dificil', 'O total pago pode chegar a R$ 800,00 + R$ 800,00 = R$ 1.600,00. Em 10 parcelas: R$ 1.600,00 ÷ 10 = R$ 160,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d6', 'cartao-de-credito-3-quiz', 'Pelo teto legal, uma dívida de R$ 2.400,00 pode gerar, no máximo, quanto de juros somados?', array['R$ 2.400,00', 'R$ 240,00', 'R$ 1.200,00', 'R$ 4.800,00']::text[], 0, 'dificil', 'O teto é de 100% do valor em aberto: no máximo R$ 2.400,00 de juros, o que dá um total de R$ 4.800,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d7', 'cartao-de-credito-3-quiz', 'R$ 3.000,00 parcelados em 12 vezes a 3% ao mês, pela tabela Price. Quanto vai de juros no total?', array['R$ 360,00', 'R$ 301,39', 'R$ 616,68', 'R$ 900,00']::text[], 2, 'dificil', 'A parcela é de R$ 301,39. Total pago: R$ 3.616,68. Juros: R$ 616,68.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d8', 'cartao-de-credito-3-quiz', 'R$ 1.000,00 a 5% ao mês, pela tabela Price: quanto o parcelamento em 12 vezes custa de juros a mais do que em 6 vezes?', array['R$ 353,96', 'R$ 182,12', 'R$ 100,00', 'R$ 171,84']::text[], 3, 'dificil', 'Em 6 vezes o total é R$ 1.182,12; em 12 vezes, R$ 1.353,96. A diferença é de R$ 171,84.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d9', 'cartao-de-credito-3-quiz', 'R$ 1.000,00 em 6 parcelas: a 4% ao mês o total é R$ 1.144,56; a 6% ao mês, R$ 1.220,16. Quanto custa a mais a taxa maior?', array['R$ 75,60', 'R$ 2,00', 'R$ 60,00', 'R$ 200,00']::text[], 0, 'dificil', 'R$ 1.220,16 − R$ 1.144,56 = R$ 75,60. Uma taxa maior encarece a parcela e o total.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('cartao-de-credito-3-d10', 'cartao-de-credito-3-quiz', 'Uma dívida de R$ 1.000,00 foi parcelada em 12 vezes de R$ 190,00. A cobrança é regular, pelo teto legal?', array['Sim, qualquer taxa é permitida', 'Não: os juros de R$ 1.280,00 passam do teto', 'Sim, porque a parcela é menor que R$ 1.000,00', 'Não, porque o prazo deveria ser menor']::text[], 1, 'dificil', 'Total pago: R$ 190,00 × 12 = R$ 2.280,00. Juros: R$ 1.280,00, acima dos R$ 1.000,00 permitidos, ou seja, a cobrança estaria irregular.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f2', 'inflacao-e-investimentos-1-quiz', 'O que significa perder poder de compra?', array['Receber menos salário todo mês', 'Ter o cartão bloqueado pelo banco', 'Pagar mais impostos no ano', 'Comprar menos com o mesmo dinheiro']::text[], 3, 'facil', 'Com a inflação, os preços sobem. A mesma quantia passa a comprar menos, e isso é perder poder de compra.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f3', 'inflacao-e-investimentos-1-quiz', 'Quem calcula o IPCA, o índice oficial de inflação do Brasil?', array['A Receita Federal', 'O IBGE', 'Cada banco, por conta própria', 'O Ministério da Saúde']::text[], 1, 'facil', 'O IPCA é calculado pelo IBGE, o Instituto Brasileiro de Geografia e Estatística.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f4', 'inflacao-e-investimentos-1-quiz', 'O que o IPCA acompanha?', array['O valor do dólar frente ao real', 'O preço das ações negociadas na bolsa', 'Os preços de produtos e serviços do dia a dia', 'O rendimento mensal da poupança']::text[], 2, 'facil', 'O IPCA acompanha os preços de uma cesta de bens e serviços consumidos pelas famílias e mostra quanto eles variaram.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f5', 'inflacao-e-investimentos-1-quiz', 'Se os preços sobem e o dinheiro guardado em casa não rende, o que acontece com ele?', array['Compra menos do que antes', 'Compra mais do que antes', 'Continua comprando exatamente o mesmo', 'Vira um investimento']::text[], 0, 'facil', 'Dinheiro parado perde valor: o valor nominal é o mesmo, mas ele compra menos.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f6', 'inflacao-e-investimentos-1-quiz', 'Qual destes é um sinal de inflação?', array['Os mesmos produtos custam mais que antes', 'Os preços caem em todas as lojas', 'O salário dobra de um mês para o outro', 'A moeda é trocada por outra']::text[], 0, 'facil', 'Inflação é o aumento geral e contínuo dos preços. Ver os mesmos produtos mais caros é o sinal mais direto.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f7', 'inflacao-e-investimentos-1-quiz', 'No cálculo da inflação, o que é a "cesta" de produtos?', array['Uma cesta de alimentos entregue pelo governo', 'Uma carteira de ações', 'Um conjunto de bens e serviços que as famílias consomem', 'Um tipo de aplicação financeira']::text[], 2, 'facil', 'A cesta reúne produtos e serviços do dia a dia, como alimentação, transporte e moradia. Acompanhar o preço dela mostra a inflação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f8', 'inflacao-e-investimentos-1-quiz', 'Qual atitude pode ajudar a proteger o poder de compra do dinheiro?', array['Guardá-lo debaixo do colchão', 'Investir para que o dinheiro renda', 'Gastá-lo todo no primeiro dia', 'Ignorar o aumento dos preços']::text[], 1, 'facil', 'Investir ajuda o dinheiro a render e a acompanhar o aumento dos preços, o que protege o poder de compra.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-f9', 'inflacao-e-investimentos-1-quiz', 'Em que forma a inflação costuma ser informada?', array['Em reais por mês', 'Em número de produtos vendidos', 'Em pontos de risco', 'Em percentual de aumento dos preços']::text[], 3, 'facil', 'A inflação aparece como um percentual, por exemplo 5% ao ano: é quanto os preços subiram no período.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m4', 'inflacao-e-investimentos-1-quiz', 'Com inflação de 4% ao ano, um produto de R$ 250,00 passa a custar quanto depois de 1 ano?', array['R$ 254,00', 'R$ 260,00', 'R$ 275,00', 'R$ 290,00']::text[], 1, 'medio', 'R$ 250,00 × 1,04 = R$ 260,00. Um aumento de 4% sobre R$ 250,00 são R$ 10,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m5', 'inflacao-e-investimentos-1-quiz', 'Um aluguel de R$ 1.200,00 sobe 5%. Qual é o novo valor?', array['R$ 1.260,00', 'R$ 1.205,00', 'R$ 1.250,00', 'R$ 1.320,00']::text[], 0, 'medio', 'R$ 1.200,00 × 1,05 = R$ 1.260,00. O aumento foi de R$ 60,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m6', 'inflacao-e-investimentos-1-quiz', 'Com inflação de 8%, uma compra de R$ 500,00 passa a custar quanto?', array['R$ 508,00', 'R$ 550,00', 'R$ 580,00', 'R$ 540,00']::text[], 3, 'medio', 'R$ 500,00 × 1,08 = R$ 540,00. Os R$ 508,00 seriam um aumento de 8 reais, e não de 8%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m7', 'inflacao-e-investimentos-1-quiz', 'Os preços subiram 5% e o salário de R$ 3.000,00 não mudou. O que aconteceu com o poder de compra?', array['Aumentou, porque o salário é o mesmo', 'Ficou exatamente igual', 'Diminuiu: o salário compra menos que antes', 'Dobrou, por causa dos preços']::text[], 2, 'medio', 'Se os preços sobem e o salário fica igual, a mesma quantia compra menos. O poder de compra caiu.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m8', 'inflacao-e-investimentos-1-quiz', 'Um lanche de R$ 15,00 passou a custar R$ 16,50 um ano depois. Qual foi a inflação desse lanche?', array['1,5%', '15%', '10%', '8%']::text[], 2, 'medio', 'O aumento foi de R$ 16,50 − R$ 15,00 = R$ 1,50. R$ 1,50 ÷ R$ 15,00 = 0,10, ou seja, 10%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m9', 'inflacao-e-investimentos-1-quiz', 'Um salário aumentou 3% num ano em que a inflação foi de 6%. O que ocorreu com o poder de compra?', array['Diminuiu, porque os preços subiram mais', 'Aumentou, porque o salário subiu', 'Ficou igual, pois o salário subiu um pouco', 'Dobrou, por causa da inflação']::text[], 0, 'medio', 'Os preços subiram 6% e o salário, só 3%. O salário passou a comprar menos do que antes.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m10', 'inflacao-e-investimentos-1-quiz', 'Com inflação de 5% ao ano, um produto de R$ 100,00 custará quanto depois de 2 anos?', array['R$ 110,00', 'R$ 110,25', 'R$ 105,00', 'R$ 115,00']::text[], 1, 'medio', 'Ano 1: R$ 100,00 × 1,05 = R$ 105,00. Ano 2: R$ 105,00 × 1,05 = R$ 110,25. A inflação também age sobre ela mesma.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m11', 'inflacao-e-investimentos-1-quiz', 'Qual é a relação entre o IPCA e o IBGE?', array['O IPCA é o órgão e o IBGE é o índice', 'São dois nomes para a mesma coisa', 'O IBGE paga o IPCA aos brasileiros', 'O IPCA é o índice; o IBGE é quem o calcula']::text[], 3, 'medio', 'O IPCA é o índice oficial de inflação. Quem o calcula e divulga é o IBGE.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m12', 'inflacao-e-investimentos-1-quiz', 'Em qual situação o dinheiro parado perde mais poder de compra?', array['Com inflação de 3% ao ano, em vez de 9% ao ano', 'Quando a inflação é zero', 'Com inflação de 9% ao ano, em vez de 3% ao ano', 'Quando o dinheiro está em casa e não no banco']::text[], 2, 'medio', 'Quanto maior a inflação, mais rápido o dinheiro parado perde valor.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m13', 'inflacao-e-investimentos-1-quiz', 'R$ 1.000,00 ficam parados por 1 ano, com inflação de 10%. Quanto esse dinheiro compra, em valores de hoje?', array['R$ 900,00', 'R$ 1.000,00', 'R$ 1.100,00', 'R$ 909,09']::text[], 3, 'medio', 'Os preços subiram 10%. R$ 1.000,00 ÷ 1,10 = R$ 909,09: é o que se compraria hoje com esse dinheiro.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m14', 'inflacao-e-investimentos-1-quiz', 'Uma cesta de compras que custava R$ 600,00 passou a custar R$ 636,00. Qual foi a inflação dessa cesta?', array['3,6%', '6%', '36%', '0,6%']::text[], 1, 'medio', 'O aumento foi de R$ 36,00. R$ 36,00 ÷ R$ 600,00 = 0,06, ou seja, 6%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m15', 'inflacao-e-investimentos-1-quiz', 'O preço de um produto sobe de R$ 40,00 para R$ 46,00. Qual é o aumento percentual?', array['15%', '6%', '13%', '20%']::text[], 0, 'medio', 'R$ 46,00 − R$ 40,00 = R$ 6,00. R$ 6,00 ÷ R$ 40,00 = 0,15, ou seja, 15%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-m16', 'inflacao-e-investimentos-1-quiz', 'Uma pessoa guardou R$ 2.000,00 em casa por 1 ano, com inflação de 5%. Quanto custam agora as mesmas coisas que custavam R$ 2.000,00?', array['R$ 2.005,00', 'R$ 2.050,00', 'R$ 2.200,00', 'R$ 2.100,00']::text[], 3, 'medio', 'R$ 2.000,00 × 1,05 = R$ 2.100,00. O dinheiro guardado em casa continua com R$ 2.000,00 e já não compra tudo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-d1', 'inflacao-e-investimentos-1-quiz', 'Um salário de R$ 2.500,00 fica sem reajuste por 2 anos, com inflação de 6% ao ano. Quanto ele vale, em poder de compra de hoje, ao fim dos 2 anos?', array['R$ 2.200,00', 'R$ 2.350,00', 'R$ 2.224,99', 'R$ 2.500,00']::text[], 2, 'dificil', 'Em 2 anos os preços sobem 1,06² = 1,1236. O salário equivale a R$ 2.500,00 ÷ 1,1236 = R$ 2.224,99.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-d2', 'inflacao-e-investimentos-1-quiz', 'Com inflação de 5% ao ano, quanto custará, daqui a 3 anos, o que hoje custa R$ 1.000,00?', array['R$ 1.157,63', 'R$ 1.150,00', 'R$ 1.050,00', 'R$ 1.200,00']::text[], 0, 'dificil', 'R$ 1.000,00 × 1,05³ = R$ 1.157,63. Somar 5% três vezes (R$ 1.150,00) ignora que a inflação incide sobre ela mesma.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-1-d3', 'inflacao-e-investimentos-1-quiz', 'Num ano a inflação foi de 4% e, no seguinte, de 6%. Quanto os preços subiram nos dois anos juntos?', array['10,00%', '10,24%', '5,00%', '24,00%']::text[], 1, 'dificil', '(1,04 × 1,06) − 1 = 10,24%. Os aumentos se acumulam um sobre o outro, e não apenas se somam.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f2', 'inflacao-e-investimentos-2-quiz', 'O que é rendimento nominal?', array['O rendimento "no papel", sem descontar inflação', 'O rendimento já descontada a inflação', 'O valor dos impostos cobrados no resgate', 'O valor que o banco cobra por mês de tarifa']::text[], 0, 'facil', 'O rendimento nominal é o que aparece no extrato. Para saber o ganho de verdade, é preciso descontar a inflação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f3', 'inflacao-e-investimentos-2-quiz', 'Quando a aplicação rende menos que a inflação, o ganho real é:', array['Positivo, porque o saldo aumentou', 'Sempre igual a zero', 'Negativo: o poder de compra diminui', 'Igual ao rendimento nominal']::text[], 2, 'facil', 'O saldo até cresce, mas os preços crescem mais. Dá para comprar menos do que antes.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f4', 'inflacao-e-investimentos-2-quiz', 'Qual é a conta aproximada do ganho real?', array['Rendimento mais inflação', 'Rendimento dividido pela inflação', 'Rendimento vezes inflação', 'Rendimento menos inflação']::text[], 3, 'facil', 'Uma aproximação do ganho real é o rendimento menos a inflação. A conta exata é (1 + rendimento) ÷ (1 + inflação) − 1.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f5', 'inflacao-e-investimentos-2-quiz', 'Quando o poder de compra de uma aplicação aumenta?', array['Quando o rendimento é menor que a inflação', 'Quando o rendimento é maior que a inflação', 'Quando a inflação sobe', 'Nunca aumenta']::text[], 1, 'facil', 'O poder de compra cresce quando o dinheiro rende mais do que os preços sobem.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-f6', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 6% em um ano com inflação de 6%. O ganho real é:', array['De cerca de 12%', 'Próximo de zero', 'De cerca de 6%', 'De cerca de 36%']::text[], 1, 'facil', 'Se o rendimento é igual à inflação, o dinheiro apenas acompanha os preços: o poder de compra fica praticamente igual.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m3', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 8% ao ano e a inflação é de 5%. Qual é o ganho real, aproximadamente?', array['3,00%', '13,00%', '2,86%', '1,60%']::text[], 2, 'medio', '(1,08 ÷ 1,05) − 1 = 2,86%. A conta aproximada, 8% − 5% = 3%, é próxima, mas não é exata.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m4', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 12% ao ano e a inflação é de 6%. Qual é o ganho real, aproximadamente?', array['5,66%', '6,00%', '18,00%', '2,00%']::text[], 0, 'medio', '(1,12 ÷ 1,06) − 1 = 5,66%, um pouco abaixo dos 6% da conta aproximada.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m5', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 5% ao ano e a inflação é de 7%. Qual é o ganho real, aproximadamente?', array['Ganho de 2,00%', 'Perda de 2,00%', 'Ganho de 12,00%', 'Perda de 1,87%']::text[], 3, 'medio', '(1,05 ÷ 1,07) − 1 = −1,87%. O sinal negativo mostra perda de poder de compra.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m6', 'inflacao-e-investimentos-2-quiz', 'R$ 1.000,00 rendem 10% ao ano e a inflação é de 4%. Depois de 1 ano, o saldo vale quanto em poder de compra de hoje?', array['R$ 1.100,00', 'R$ 1.060,00', 'R$ 1.057,69', 'R$ 1.040,00']::text[], 2, 'medio', 'O saldo nominal é R$ 1.100,00. Descontando a inflação: R$ 1.100,00 ÷ 1,04 = R$ 1.057,69.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m7', 'inflacao-e-investimentos-2-quiz', 'Com inflação de 5%, qual destas aplicações dá o maior ganho real?', array['A que rende 9% ao ano', 'A que rende 6% ao ano', 'A que rende 4% ao ano', 'A que rende 5% ao ano']::text[], 0, 'medio', 'O maior rendimento nominal dá o maior ganho real quando a inflação é a mesma: 9% contra 5% de inflação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m8', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 3% e a inflação é de 5%. R$ 2.000,00 viram R$ 2.060,00, mas para manter o poder de compra seriam necessários:', array['R$ 2.000,00', 'R$ 2.060,00', 'R$ 2.150,00', 'R$ 2.100,00']::text[], 3, 'medio', 'Com inflação de 5%, o que custava R$ 2.000,00 passa a custar R$ 2.100,00. Os R$ 2.060,00 não acompanham os preços.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m9', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 15% ao ano e a inflação é de 9%. Qual é o ganho real, aproximadamente?', array['6,00%', '5,50%', '24,00%', '1,35%']::text[], 1, 'medio', '(1,15 ÷ 1,09) − 1 = 5,50%. A subtração simples daria 6%, um pouco acima.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m10', 'inflacao-e-investimentos-2-quiz', 'A inflação sobe de 4% para 8%, e a aplicação continua rendendo 6%. O que muda no ganho real?', array['Continua o mesmo, pois o rendimento é 6%', 'Fica ainda maior', 'Passa a ser sempre zero', 'Passa de cerca de 1,92% para cerca de −1,85%']::text[], 3, 'medio', 'Com inflação de 4%: (1,06 ÷ 1,04) − 1 = 1,92%. Com 8%: (1,06 ÷ 1,08) − 1 = −1,85%. O rendimento nominal é o mesmo, mas o ganho real não é.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m11', 'inflacao-e-investimentos-2-quiz', 'Por que um rendimento nominal alto não garante ganho real positivo?', array['Porque a inflação pode ser maior que o rendimento', 'Porque o banco desconta a inflação do extrato', 'Porque rendimento nominal não existe de verdade', 'Porque o ganho real só vale para ações']::text[], 0, 'medio', 'O ganho real depende da comparação com a inflação. Um rendimento alto num período de inflação ainda maior pode dar perda real.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m12', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 9% e a inflação é 3%. Qual é o ganho real pela conta aproximada?', array['12 pontos percentuais', '6 pontos percentuais', '27 pontos percentuais', '3 pontos percentuais']::text[], 1, 'medio', 'A conta aproximada é rendimento menos inflação: 9% − 3% = 6 pontos percentuais.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m13', 'inflacao-e-investimentos-2-quiz', 'Qual destas é a conta exata do ganho real?', array['Multiplicar (1 + rendimento) por (1 + inflação) e subtrair 1', 'Somar o rendimento e a inflação', 'Dividir (1 + rendimento) por (1 + inflação) e subtrair 1', 'Dividir o rendimento pela inflação']::text[], 2, 'medio', 'A conta exata divide os fatores: (1 + rendimento) ÷ (1 + inflação) − 1. A subtração simples é só uma aproximação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-m14', 'inflacao-e-investimentos-2-quiz', 'O salário sobe 4% e a inflação é de 6%. O que acontece com o poder de compra?', array['Sobe cerca de 2,00%', 'Fica exatamente igual', 'Cai cerca de 10,00%', 'Cai cerca de 1,89%']::text[], 3, 'medio', '(1,04 ÷ 1,06) − 1 = −1,89%. O salário aumentou, mas menos do que os preços.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d2', 'inflacao-e-investimentos-2-quiz', 'Uma aplicação rende 11% ao ano por 2 anos e a inflação é de 5% ao ano. Qual é o ganho real acumulado, aproximadamente?', array['12,00%', '5,71%', '11,76%', '6,00%']::text[], 2, 'dificil', '(1,11² ÷ 1,05²) − 1 = 11,76%. Os ganhos reais de cada ano também se acumulam.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d3', 'inflacao-e-investimentos-2-quiz', 'R$ 5.000,00 rendem 9% ao ano e a inflação é de 4%. Depois de 1 ano, o saldo vale quanto em poder de compra de hoje?', array['R$ 5.450,00', 'R$ 5.240,38', 'R$ 5.250,00', 'R$ 5.200,00']::text[], 1, 'dificil', 'O saldo é R$ 5.450,00. Em valores de hoje: R$ 5.450,00 ÷ 1,04 = R$ 5.240,38.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d4', 'inflacao-e-investimentos-2-quiz', 'Para ter ganho real de 3% com inflação de 5%, qual deve ser o rendimento nominal?', array['8,15%', '8,00%', '2,00%', '15,00%']::text[], 0, 'dificil', '(1,03 × 1,05) − 1 = 8,15%. A conta aproximada daria 8%, e a exata dá um pouco mais.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d5', 'inflacao-e-investimentos-2-quiz', 'Num ano a aplicação A rende 10% com inflação de 6%. Em outro, a aplicação B rende 7% com inflação de 2%. Qual teve o maior ganho real?', array['A aplicação B, com 4,90% contra 3,77%', 'A aplicação A, porque 10% é maior que 7%', 'As duas tiveram o mesmo ganho real', 'Não dá para comparar']::text[], 0, 'dificil', 'A: (1,10 ÷ 1,06) − 1 = 3,77%. B: (1,07 ÷ 1,02) − 1 = 4,90%. O que importa é a diferença para a inflação.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d6', 'inflacao-e-investimentos-2-quiz', 'Um fundo rendeu 14% em um ano em que a inflação foi de 6,5%. Qual foi o ganho real?', array['7,50%', '20,50%', '6,50%', '7,04%']::text[], 3, 'dificil', '(1,14 ÷ 1,065) − 1 = 7,04%. A subtração simples daria 7,50%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d7', 'inflacao-e-investimentos-2-quiz', 'O ganho real foi de −2% num ano com inflação de 5%. Qual foi, aproximadamente, o rendimento nominal?', array['7,00%', '2,90%', '−2,00%', '5,00%']::text[], 1, 'dificil', 'Se (1 + rendimento) ÷ 1,05 = 0,98, o rendimento é 0,98 × 1,05 − 1 = 2,90%.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-2-d8', 'inflacao-e-investimentos-2-quiz', 'R$ 10.000,00 ficam 3 anos numa aplicação de 8% ao ano, com inflação de 5% ao ano. Quanto vale o saldo final, em poder de compra do início?', array['R$ 12.597,12', 'R$ 11.500,00', 'R$ 10.881,87', 'R$ 10.000,00']::text[], 2, 'dificil', 'Saldo nominal: R$ 10.000,00 × 1,08³ = R$ 12.597,12. Descontando 1,05³: R$ 10.881,87.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f2', 'inflacao-e-investimentos-3-quiz', 'O que é um ativo?', array['Uma dívida que gera juros altos', 'Um bem que pode gerar renda ou valorização', 'Um imposto cobrado sobre o patrimônio', 'Um tipo de conta bancária comum']::text[], 1, 'facil', 'Ativos são bens ou aplicações, como ações, títulos e imóveis, que podem gerar renda ou valorizar.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f3', 'inflacao-e-investimentos-3-quiz', 'O que é risco, em investimentos?', array['A garantia de ganho no fim do prazo', 'O nome de uma taxa de juros', 'A chance de o resultado ser pior que o esperado', 'O valor que o banco cobra para guardar o dinheiro']::text[], 2, 'facil', 'Todo ativo tem risco. Risco é a possibilidade de o resultado ficar abaixo do que se esperava, inclusive com perda de dinheiro.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f4', 'inflacao-e-investimentos-3-quiz', 'Qual destes é um exemplo de ativo?', array['A fatura do cartão', 'A conta de luz', 'A parcela de um empréstimo', 'Ações de uma empresa']::text[], 3, 'facil', 'Ações são ativos: dão direito a uma parte de uma empresa e podem gerar renda ou valorização.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f5', 'inflacao-e-investimentos-3-quiz', 'Qual ditado resume a ideia de diversificar?', array['Não pôr os ovos na mesma cesta', 'Devagar se vai ao longe', 'Mais vale um pássaro na mão', 'Água mole em pedra dura']::text[], 0, 'facil', 'Diversificar é espalhar o dinheiro entre ativos diferentes, para que a queda de um não derrube tudo.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-f6', 'inflacao-e-investimentos-3-quiz', 'A diversificação elimina o risco?', array['Sim, completamente, em qualquer caso', 'Sim, mas só quando é feita nos fundos', 'Não: reduz o risco, mas não o elimina', 'Sim, mas só quando é feita nas ações']::text[], 2, 'facil', 'Diversificar reduz o risco de concentração, mas não o elimina. Nenhum investimento é livre de perdas.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m2', 'inflacao-e-investimentos-3-quiz', 'R$ 1.000,00 estão em uma única ação, que cai 20%. Quanto sobra?', array['R$ 200,00', 'R$ 800,00', 'R$ 980,00', 'R$ 1.200,00']::text[], 1, 'medio', 'R$ 1.000,00 × 0,80 = R$ 800,00. A perda foi de R$ 200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m3', 'inflacao-e-investimentos-3-quiz', 'R$ 1.000,00 foram divididos em 4 ativos de R$ 250,00. Um deles cai 40% e os outros ficam iguais. Quanto há no total?', array['R$ 900,00', 'R$ 600,00', 'R$ 750,00', 'R$ 960,00']::text[], 0, 'medio', 'O ativo que caiu vale R$ 250,00 × 0,60 = R$ 150,00. Somando aos outros três (R$ 750,00): R$ 900,00. A perda foi de só R$ 100,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m4', 'inflacao-e-investimentos-3-quiz', 'R$ 2.000,00 estão concentrados em um ativo que cai 30%. Qual é a perda?', array['R$ 300,00', 'R$ 1.400,00', 'R$ 200,00', 'R$ 600,00']::text[], 3, 'medio', 'R$ 2.000,00 × 30% = R$ 600,00. O saldo passa a ser R$ 1.400,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m5', 'inflacao-e-investimentos-3-quiz', 'Qual é a vantagem de um fundo de investimento para quem quer diversificar?', array['Garante lucro todo mês, sem risco', 'Elimina qualquer risco de perda de valor', 'Só pode ser comprado por bancos e empresas', 'Junta o dinheiro de muita gente para comprar ativos']::text[], 3, 'medio', 'Um fundo reúne dinheiro de muitas pessoas e compra vários ativos, o que facilita a diversificação. Mesmo assim, ele pode ter perdas.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m6', 'inflacao-e-investimentos-3-quiz', 'Qual atitude é uma forma de diversificar?', array['Dividir o dinheiro entre ativos diferentes', 'Colocar tudo no ativo que mais subiu', 'Comprar só ações de uma mesma empresa', 'Resgatar tudo ao primeiro susto']::text[], 0, 'medio', 'Diversificar é espalhar o dinheiro entre ativos diferentes, para que a queda de um deles não derrube o conjunto.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m7', 'inflacao-e-investimentos-3-quiz', 'R$ 3.000,00 foram divididos igualmente em 3 ativos. Um perdeu 50%, outro subiu 20% e o terceiro ficou igual. Qual é o total?', array['R$ 3.000,00', 'R$ 2.500,00', 'R$ 2.700,00', 'R$ 3.300,00']::text[], 2, 'medio', 'Ativo 1: R$ 1.000,00 × 0,50 = R$ 500,00. Ativo 2: R$ 1.000,00 × 1,20 = R$ 1.200,00. Ativo 3: R$ 1.000,00. Total: R$ 2.700,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m8', 'inflacao-e-investimentos-3-quiz', 'Qual afirmação sobre fundos de investimento está correta?', array['Fundos garantem lucro', 'Todo fundo pode ter perdas', 'Fundos nunca perdem para a inflação', 'Fundos só existem para quem é muito rico']::text[], 1, 'medio', 'Os fundos reúnem ativos, mas o resultado depende do que eles compram. Qualquer fundo pode ter perdas.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m9', 'inflacao-e-investimentos-3-quiz', 'Qual carteira é mais diversificada?', array['A que divide o dinheiro em quatro ativos diferentes', 'A que coloca todo o dinheiro em ações de uma única empresa', 'A que compra só um tipo de ativo, de uma única empresa', 'A que muda de ativo todo dia']::text[], 0, 'medio', 'Quanto mais espalhado o dinheiro entre ativos diferentes, menor o efeito da queda de um só.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m10', 'inflacao-e-investimentos-3-quiz', 'Entre dois ativos, um tem resultado muito incerto e o outro é mais previsível. Qual tem maior risco?', array['O mais previsível', 'O de resultado mais incerto', 'Os dois têm o mesmo risco', 'Nenhum dos dois tem risco']::text[], 1, 'medio', 'Risco é a chance de o resultado ser diferente do esperado. Quanto mais incerto o resultado, maior o risco.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m11', 'inflacao-e-investimentos-3-quiz', 'R$ 500,00 estão num ativo que cai 10%. Qual é a perda?', array['R$ 5,00', 'R$ 10,00', 'R$ 50,00', 'R$ 450,00']::text[], 2, 'medio', 'R$ 500,00 × 10% = R$ 50,00. O saldo fica em R$ 450,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-m12', 'inflacao-e-investimentos-3-quiz', 'Em qual situação a diversificação mais protege o investidor?', array['Quando todos os ativos sobem juntos', 'Quando o dinheiro está num só ativo', 'Quando a inflação é zero', 'Quando só um dos ativos da carteira cai']::text[], 3, 'medio', 'Se só um ativo cai, os outros seguram o resultado. Num único ativo, a queda atinge todo o dinheiro.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d3', 'inflacao-e-investimentos-3-quiz', 'R$ 4.000,00 foram divididos em 5 partes iguais. Uma parte perde 50% e as outras ficam iguais. Qual é a perda total?', array['R$ 400,00', 'R$ 2.000,00', 'R$ 800,00', 'R$ 200,00']::text[], 0, 'dificil', 'Cada parte vale R$ 800,00. Uma delas perde 50%: R$ 400,00. A perda é de R$ 400,00, ou seja, 10% do total.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d4', 'inflacao-e-investimentos-3-quiz', 'Concentrados em um ativo, R$ 4.000,00 perdem 50%. Divididos em 5 partes iguais, só uma parte perde 50%. Quanto a diversificação reduz a perda?', array['R$ 400,00', 'R$ 2.000,00', 'R$ 1.200,00', 'R$ 1.600,00']::text[], 3, 'dificil', 'Concentrado: perda de R$ 2.000,00. Diversificado: perda de R$ 400,00. A diferença é de R$ 1.600,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d5', 'inflacao-e-investimentos-3-quiz', 'R$ 1.000,00 estão em cada um de 2 ativos. Um sobe 30% e o outro cai 30%. Qual é o total?', array['R$ 2.100,00', 'R$ 1.900,00', 'R$ 2.000,00: o ganho de um compensa a perda do outro', 'R$ 2.600,00']::text[], 2, 'dificil', 'O primeiro vai a R$ 1.300,00 e o segundo a R$ 700,00. Total: R$ 2.000,00. Sem a queda de um, o investidor perderia tudo o que o outro ganhasse.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d6', 'inflacao-e-investimentos-3-quiz', 'Uma carteira de R$ 5.000,00 tem 60% no ativo A e 40% no ativo B. A cai 10% e B sobe 10%. Qual é o valor final?', array['R$ 5.000,00', 'R$ 4.900,00', 'R$ 5.500,00', 'R$ 4.500,00']::text[], 1, 'dificil', 'A: R$ 3.000,00 × 0,90 = R$ 2.700,00. B: R$ 2.000,00 × 1,10 = R$ 2.200,00. Total: R$ 4.900,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d7', 'inflacao-e-investimentos-3-quiz', 'R$ 2.400,00 foram divididos em 6 ativos iguais. Dois caem 25% e os outros ficam iguais. Qual é o valor final?', array['R$ 2.000,00', 'R$ 2.200,00', 'R$ 2.300,00', 'R$ 1.800,00']::text[], 1, 'dificil', 'Cada ativo vale R$ 400,00. Cada queda de 25% tira R$ 100,00. Duas quedas: R$ 200,00. O total fica em R$ 2.200,00.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d8', 'inflacao-e-investimentos-3-quiz', 'Qual afirmação sobre concentrar todo o dinheiro num único ativo está correta?', array['Garante o maior lucro possível', 'Elimina o risco, porque só há um ativo', 'É sempre mais seguro que diversificar', 'Expõe a pessoa a perder muito se ele cair']::text[], 3, 'dificil', 'Com um único ativo, a queda dele atinge todo o dinheiro. Diversificar espalha esse risco.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d9', 'inflacao-e-investimentos-3-quiz', 'Pedro diz: "Como diversifiquei meus investimentos, não posso perder dinheiro." Qual é o erro?', array['Diversificar reduz o risco, mas não o elimina', 'Não há erro: diversificar garante lucro', 'Só ações podem perder, e ele não tem ações', 'Perda só acontece quando o dinheiro está concentrado']::text[], 0, 'dificil', 'A diversificação diminui a chance de uma perda grande, mas não impede perdas. Nenhum investimento é livre de risco.', true) on conflict (id) do nothing;
insert into public.questoes (id, quiz_id, enunciado, alternativas, resposta_correta, nivel_dificuldade, explicacao, ativa) values ('inflacao-e-investimentos-3-d10', 'inflacao-e-investimentos-3-quiz', 'Um fundo tem 10 ativos de mesmo valor. Um deles vai a zero e os outros ficam iguais. Qual foi a perda do fundo?', array['100%', '50%', '10%', '1%']::text[], 2, 'dificil', 'Cada ativo é 10% do fundo. Perder um deles inteiro é perder 10% do total. Num único ativo, a perda seria de 100%.', true) on conflict (id) do nothing;
